window.COURSES=window.COURSES||{};window.COURSES.markdown={"id":"markdown","name":"Markdown","title":"Markdown Forge","updated":"2026-10-23","hours":72,"description":"Escreva documentos claros e portáveis, do primeiro README a manuais técnicos, com CommonMark, GFM, revisão e manutenção.","prerequisites":["Nenhuma experiência prévia de programação é exigida.","Editor de texto e visualizador de Markdown; use um preview local com o dialeto declarado.","Saber criar pastas e arquivos. Markdown organiza conteúdo; não exige um compilador de linguagem."],"outcome":"Entregar um conjunto de documentação de ordens de serviço e estoque com README, guias, referências, decisões e revisão de links e acessibilidade.","extension":"md","codeLanguage":"markdown","setup":[{"title":"Arquivo e preview","text":"Crie uma pasta markdown-forge e uma subpasta por aula. Salve o exemplo com o nome indicado e abra o preview de Markdown do seu editor. Compare também o arquivo de texto, pois a legibilidade da fonte faz parte do trabalho."},{"title":"Declare o renderizador","text":"Registre qual visualizador e dialeto você usa. CommonMark define uma base; GFM acrescenta recursos. Tabelas, checklists, Mermaid, front matter e MDX não são todos parte da mesma especificação."},{"title":"Verifique a entrega","text":"O editor da plataforma guarda o texto; ele não renderiza nem publica seu Markdown. Confira títulos, listas, links e exemplos no destino real. Imagens e links relativos dependem dos arquivos e das pastas indicados na aula."}],"references":[{"title":"CommonMark 0.31.2","description":"Especificação primária de blocos e conteúdo inline; base portátil da trilha.","url":"https://spec.commonmark.org/0.31.2/"},{"title":"Especificação GFM","description":"Extensões de tabelas, listas de tarefas, autolinks e texto riscado.","url":"https://github.github.com/gfm/"},{"title":"Sintaxe no GitHub","description":"Comportamento do renderizador GitHub, links, imagens e navegação.","url":"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax"},{"title":"Blocos de código","description":"Cercas, identificadores de linguagem e realce no GitHub.","url":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-and-highlighting-code-blocks"},{"title":"Tabelas no GitHub","description":"Organização de dados tabulares e escape de barras verticais.","url":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/organizing-information-with-tables"},{"title":"Seções recolhíveis","description":"Uso de details e summary no renderizador GitHub.","url":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/organizing-information-with-collapsed-sections"},{"title":"Diagramas no GitHub","description":"Mermaid como extensão do ambiente, com limites de compatibilidade.","url":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-diagrams"},{"title":"README como entrada de um repositório","description":"Finalidade do README, links relativos e navegação entre seções no GitHub.","url":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes"},{"title":"Front matter no Jekyll","description":"Contrato específico de metadados do gerador, separado da base Markdown.","url":"https://jekyllrb.com/docs/front-matter/"},{"title":"O formato MDX","description":"Diferenças entre texto Markdown, JSX e expressões num pipeline próprio.","url":"https://mdxjs.com/docs/what-is-mdx/"}],"levels":[{"id":1,"title":"Texto e estrutura","tag":"Fundamentos","hours":6,"summary":"Leia o arquivo-fonte e transforme um texto simples em uma página com hierarquia.","skills":["Arquivo .md","Títulos","Ênfase"],"project":"Apresentação de um projeto","deliverables":["README com título, objetivo e público.","Parágrafos e destaque com função clara.","Registro do preview e do dialeto usado."],"rubric":["A fonte continua legível sem renderização.","Os títulos representam a estrutura real do conteúdo.","Ênfase e código inline são usados com intenção."],"challenge":[{"question":"Você abriu o mesmo arquivo no editor e no preview. Um mostra # antes do nome e o outro mostra um título grande. O que essa diferença indica?","options":["O preview escreveu um programa diferente sem salvar.","O caractere # nunca faz parte de uma fonte Markdown.","A fonte usa marcação que o preview interpreta como uma estrutura de título.","O título grande prova que os links locais foram conferidos."],"answer":2,"explanation":"A leitura visual pode ocultar os delimitadores da estrutura; isso não altera o texto-fonte nem comprova outras verificações."},{"question":"Um autor usou seis # numa seção irmã das demais de nível2 apenas para diminuir a fonte. Qual revisão melhora a organização?","options":["Acrescentar ainda mais # até atingir uma fonte menor.","Transformar todos os parágrafos em títulos de nível6.","Excluir a estrutura e usar apenas espaços de alinhamento.","Manter o nível coerente com as seções irmãs e deixar o tema cuidar do tamanho."],"answer":3,"explanation":"O nível do título comunica hierarquia. Usá-lo apenas como controle visual prejudica navegação e manutenção."},{"question":"Um manual deve mostrar o nome exato arquivo*.json. Qual escolha expressa melhor que se trata de um literal?","options":["Envolver o nome em código inline, preservando o asterisco como parte do nome.","Usar apenas itálico para que o leitor deduza o caractere.","Converter o nome em um título principal.","Remover o asterisco sem explicar a mudança."],"answer":0,"explanation":"A forma literal distingue o nome que precisa ser reconhecido da explicação ao seu redor."}]},{"id":2,"title":"Listas e blocos","tag":"Fundamentos","hours":6,"summary":"Organize procedimentos, agrupamentos e observações sem depender de alinhamento visual.","skills":["Listas","Aninhamento","Citações"],"project":"Procedimento de conferência","deliverables":["Passos de conferência em sequência.","Subitens ligados ao passo correto.","Observação separada do procedimento principal."],"rubric":["A lista ordenada mantém ordem compreensível.","Aninhamento é verificado no preview.","Nenhuma instrução essencial fica ambígua numa citação."],"challenge":[{"question":"Na conferência, a comparação de saldo só faz sentido depois de identificar a OS. Como representar essa dependência?","options":["Ordenar as ações alfabeticamente.","Usar passos ordenados e colocar a identificação antes da comparação.","Usar marcadores sem explicar a dependência.","Esconder a identificação numa nota opcional sem referência."],"answer":1,"explanation":"A sequência deve refletir os pré-requisitos reais da tarefa; números sozinhos não corrigem uma ordem incoerente."},{"question":"Ao passar de itens de um dígito para itens como10., um subitem saiu do pai no preview. Qual critério deve orientar o ajuste?","options":["Aplicar sempre exatamente um espaço a qualquer lista.","Presumir que listas ordenadas não aceitam subitens.","Alinhar o recuo pelo início do conteúdo do item pai e conferir o bloco resultante.","Trocar todos os marcadores por imagens."],"answer":2,"explanation":"A largura do marcador participa do recuo necessário; uma quantidade fixa de espaços não resolve todo caso."},{"question":"Uma citação contém a fala fictícia do operador. O autor quer usá-la como única prova de que a OS foi validada. Qual é o problema?","options":["Toda citação é automaticamente uma confirmação de sistema.","O sinal > transforma a fala num teste executado.","Falas fictícias sempre documentam uma operação real.","O bloco apenas representa uma fala; a conclusão exige critérios e conferência da evidência pertinente."],"answer":3,"explanation":"Atribuir e marcar uma citação não verifica a afirmação nem executa o procedimento descrito."}]},{"id":3,"title":"Código e caracteres","tag":"Fundamentos","hours":6,"summary":"Mostre comandos e sintaxe sem que o renderizador os confunda com formatação.","skills":["Cercas","Escapes","Quebras de linha"],"project":"Guia de exemplos copiáveis","deliverables":["Trechos de código com contexto e resultado esperado.","Exemplo de Markdown exibido como texto.","Convenção explícita de quebras e linhas vazias."],"rubric":["As cercas abrem e fecham corretamente.","O conteúdo copiado conserva caracteres necessários.","A leitura não depende de uma quebra suave específica."],"challenge":[{"question":"Um guia mostra entrada JSON e saída do programa na mesma cerca sem rótulos. Qual revisão reduz erro de cópia?","options":["Separar entrada e saída em blocos e explicar a função de cada um.","Colorir os dois trechos sem dizer o que representam.","Adicionar um prompt a todas as linhas de saída.","Retirar as explicações para parecer um comando único."],"answer":0,"explanation":"O leitor precisa saber o que fornecer, o que executar e o que apenas comparar como resultado."},{"question":"Uma cerca externa foi aberta com quatro crases e fechada com apenas três. O texto seguinte virou código. O que corrigir?","options":["Reduzir todos os títulos para texto simples.","Usar um fechamento do mesmo tipo com comprimento suficiente para fechar a cerca externa.","Trocar a extensão do arquivo por .json.","Adicionar negrito à primeira linha fora do bloco."],"answer":1,"explanation":"Um fechamento curto não encerra a cerca externa; o restante pode continuar dentro do bloco literal."},{"question":"Um revisor quer criar duas ideias independentes, mas usou apenas uma mudança de linha. Qual é a correção mais adequada?","options":["Aumentar a largura da janela para garantir dois blocos.","Colocar um espaço no fim de qualquer palavra.","Inserir uma linha vazia para formar dois parágrafos.","Presumir que toda quebra suave cria parágrafos separados."],"answer":2,"explanation":"Quebras visuais e parágrafos são estruturas distintas. Uma linha vazia torna a divisão de blocos explícita."}]},{"id":4,"title":"Links e caminhos","tag":"Intermediário","hours":6,"summary":"Construa navegação com rótulos úteis, referências e caminhos coerentes.","skills":["Links","Referências","Caminhos relativos"],"project":"Índice de documentação","deliverables":["Índice com rótulos que descrevem o destino.","Links por referência reutilizados com propósito.","Mapa de arquivos e caminhos relativos."],"rubric":["Links são conferidos a partir do arquivo que os contém.","As referências são únicas e resolvidas.","Âncoras geradas são verificadas no renderizador escolhido."],"challenge":[{"question":"O texto do link diz Manual de estoque, mas o destino abre uma página de sintaxe Markdown. O arquivo é sintaticamente válido. O que ainda falha?","options":["A existência do caractere ] no arquivo.","A obrigação de usar sempre URL visível como rótulo.","A regra de que um link válido dispensa qualquer revisão.","A coerência entre o rótulo e o assunto realmente encontrado no destino."],"answer":3,"explanation":"Links também precisam de precisão editorial; um destino acessível pode ser o destino errado."},{"question":"Cinco frases usam uma definição de link por referência. O endereço central foi trocado para outra fonte. O que revisar?","options":["Todos os usos e seus rótulos, além de conferir se o novo destino continua adequado.","Apenas a cor de uma das frases.","Nada, pois a centralização garante o mesmo significado.","Somente o nome do arquivo README."],"answer":0,"explanation":"Centralizar facilita a troca de URL, mas não preserva automaticamente a relação semântica de cada uso."},{"question":"docs/GUIA.md precisa ligar a docs/REFERENCIA.md, no mesmo diretório. Qual caminho relativo é adequado nesse cenário?","options":["docs/REFERENCIA.md","REFERENCIA.md","../docs/docs/REFERENCIA.md","GUIA.md/REFERENCIA.md"],"answer":1,"explanation":"O ponto de partida é o próprio guia dentro de docs. Repetir docs levaria a uma subpasta diferente."}]},{"id":5,"title":"Imagens e leitura acessível","tag":"Intermediário","hours":6,"summary":"Use conteúdo visual e estrutura que continuem informativos para leitores diferentes.","skills":["Texto alternativo","Hierarquia","Relatórios"],"project":"Relatório de uma OS","deliverables":["Relatório com resumo textual independente de imagens.","Figura local com alternativa descritiva quando usada.","Conteúdo dividido por tarefa e estado."],"rubric":["O sentido não depende apenas de cor ou imagem.","As figuras citadas existem ou são claramente tarefas de criação.","Títulos e rótulos são compreensíveis fora do contexto visual."],"challenge":[{"question":"Uma figura contém números essenciais e tem texto alternativo apenas Foto. Como melhorar o documento?","options":["Manter Foto e exigir que todos consigam ver a imagem.","Remover todos os valores do parágrafo para evitar repetição.","Explicar os números relevantes na alternativa e, quando necessário, no corpo do texto.","Usar o nome do arquivo do autor como descrição."],"answer":2,"explanation":"A figura precisa de informação equivalente ao seu papel; conteúdo complexo também pode exigir descrição fora da imagem."},{"question":"O estado de uma OS é indicado só como o quadrado verde. Qual revisão torna a orientação mais clara?","options":["Trocar verde por outro tom sem texto.","Aumentar a quantidade de imagens decorativas.","Deixar o significado apenas numa legenda ausente.","Escrever o estado em palavras e dizer qual ação ele permite ou exige."],"answer":3,"explanation":"O leitor não deve depender de percepção de cor ou do mesmo tema para compreender o estado."},{"question":"O relatório afirma que uma evidência foi anexada, mas não houve conferência de legibilidade. Qual conclusão respeita esse escopo?","options":["Registrar a existência do arquivo e manter a legibilidade como verificação pendente.","Declarar que toda a instalação está correta.","Confirmar o pagamento porque o Markdown abre.","Omitir a pendência para tornar o relatório mais curto."],"answer":0,"explanation":"Disponibilidade do recurso e avaliação do conteúdo são fatos distintos. O relatório deve separar observação e conclusão."}]},{"id":6,"title":"Recursos GFM","tag":"Intermediário","hours":6,"summary":"Aplique extensões conhecendo os limites do destino e a alternativa em texto.","skills":["Tabelas","Checklists","Dialetos"],"project":"Checklist e matriz de serviços","deliverables":["Matriz pequena de estados e efeitos.","Checklist de evidências e revisão.","Declaração dos recursos GFM utilizados."],"rubric":["A tabela tem cabeçalho e separador válidos.","Checklist não é confundido com controle de execução automático.","Documento tem alternativa compreensível em CommonMark."],"challenge":[{"question":"Uma tabela tem duas colunas, mas um valor literal contém A|B e virou uma terceira célula. Qual ajuste é apropriado no GFM?","options":["Adicionar mais barras aleatórias ao final de todas as linhas.","Escapar a barra vertical da célula conforme a sintaxe GFM e conferir o número de colunas.","Remover o cabeçalho obrigatório da tabela.","Transformar a barra em uma regra automática de estoque."],"answer":1,"explanation":"A barra participa da estrutura da tabela; o conteúdo literal precisa ser representado sem criar uma nova separação."},{"question":"Uma tarefa Revisar links está marcada, mas os arquivos foram movidos depois. O que o responsável deve fazer?","options":["Usar a marca antiga como prova do conteúdo novo.","Apagar a tarefa sem conferir qualquer destino.","Reabrir a verificação afetada, corrigir os caminhos e registrar nova conferência.","Marcar todas as outras tarefas para compensar."],"answer":2,"explanation":"A evidência de uma revisão vale para o contexto conferido; mudanças podem invalidar parte dessa afirmação."},{"question":"Um texto riscado contém a regra antiga e o novo procedimento não foi escrito em nenhum lugar. Qual revisão é necessária?","options":["Presumir que riscar uma frase define sozinho a regra contrária.","Adicionar outra URL direta sem explicar o procedimento.","Afirmar que todo leitor receberá a mesma apresentação do riscado.","Declarar a regra vigente explicitamente e deixar o trecho antigo apenas como histórico."],"answer":3,"explanation":"A apresentação de uma retirada não descreve necessariamente qual instrução deve ser seguida agora."}]},{"id":7,"title":"HTML e comportamento do renderizador","tag":"Avançado","hours":6,"summary":"Distinga sintaxe de renderização, apresentação e sanitização.","skills":["HTML inline","Details","Sanitização"],"project":"Guia com detalhes opcionais","deliverables":["Conteúdo essencial visível por padrão.","Uma seção recolhível com rótulo descritivo.","Matriz de compatibilidade do conteúdo usado."],"rubric":["HTML não é usado para esconder pré-requisitos importantes.","Não há scripts ou handlers de evento no documento.","O comportamento é conferido no destino, sem presumir suporte universal."],"challenge":[{"question":"Uma tag funciona no preview do autor, mas é filtrada no destino compartilhado. Qual interpretação é adequada?","options":["O contrato de publicação inclui restrições além do reconhecimento sintático do HTML.","Toda filtragem prova que o arquivo .md está corrompido.","Tags reconhecidas pela sintaxe precisam ser preservadas em todo site.","O título do documento pode desativar a política do destino."],"answer":0,"explanation":"Parser, sanitização e renderização são etapas distintas; adapte o conteúdo ao ambiente em que será lido."},{"question":"Uma instrução indispensável foi colocada apenas dentro de details com summary chamado Outros. Qual melhoria ajuda o leitor?","options":["Acrescentar outra camada recolhível antes da instrução.","Deixar a instrução principal visível e reservar a área recolhível para conteúdo suplementar com rótulo específico.","Retirar o summary para o leitor adivinhar onde clicar.","Manter a regra escondida porque todo HTML é universal."],"answer":1,"explanation":"A descoberta de conteúdo essencial não deve depender de abrir uma seção opcional e mal rotulada."},{"question":"Uma equipe quer aceitar HTML no manual porque o parser o reconhece. Qual informação adicional precisa definir?","options":["A suposição de que o parser garante segurança e compatibilidade completas.","O nome de qualquer banco que não será usado.","A política do destino sobre conteúdo permitido e a alternativa quando algum recurso for removido.","Uma regra para tornar todo o texto executável."],"answer":2,"explanation":"A aceitação da sintaxe não resolve a política da publicação; o conteúdo deve continuar útil sob as restrições reais."}]},{"id":8,"title":"Documentação de uso","tag":"Avançado","hours":6,"summary":"Escreva para a tarefa do leitor, separando introdução, tutorial e consulta.","skills":["README","Tutoriais","Referência"],"project":"Kit de entrada de um projeto","deliverables":["README que orienta o primeiro contato.","Tutorial com pré-requisitos e resultado verificável.","Referência curta dos campos e estados."],"rubric":["O leitor encontra um caminho inicial claro.","Os exemplos usam dados fictícios e hipóteses explícitas.","Referência e tutorial têm objetivos distintos."],"challenge":[{"question":"O README começa com vinte páginas de decisões e não explica a finalidade do projeto. Qual revisão melhora a entrada?","options":["Mover o objetivo para o fim do último exemplo.","Remover qualquer indicação de público.","Substituir toda a introdução por um logotipo sem alternativa.","Apresentar objetivo, público e primeiro percurso cedo, ligando o histórico detalhado em separado."],"answer":3,"explanation":"O ponto de entrada deve orientar o leitor antes dos detalhes usados apenas em consultas posteriores."},{"question":"Um tutorial usa saldo1 e solicitação2, mas o resultado final diz que a confirmação é permitida. Qual revisão é necessária?","options":["Revisar o raciocínio e o resultado para registrar insuficiência e a pendência adequada.","Corrigir apenas a fonte visual do resultado.","Manter o final porque tutoriais não precisam de consistência numérica.","Atribuir a diferença ao dialeto Markdown."],"answer":0,"explanation":"O procedimento precisa manter coerência com os valores e regras; sintaxe não corrige um resultado contraditório."},{"question":"Uma referência distingue conferida de confirmada, mas o guia usa as palavras como sinônimos. O que fazer?","options":["Alternar os nomes apenas para evitar repetição.","Alinhar o vocabulário com a definição de cada etapa ou revisar deliberadamente o contrato.","Remover a referência e manter os significados implícitos.","Presumir que o tema do preview indicará o estado correto."],"answer":1,"explanation":"Nomes de estados fazem parte do contrato descrito. Variação estilística não deve introduzir ambiguidade operacional."}]},{"id":9,"title":"Conjuntos de documentos","tag":"Avançado","hours":6,"summary":"Organize vários arquivos e reduza a repetição que causa divergências.","skills":["Índices","Âncoras","Convenções"],"project":"Manual dividido por público","deliverables":["Índice para operador e responsável técnico.","Links de ida e retorno entre arquivos.","Convenções e fonte principal para cada regra."],"rubric":["Nenhum arquivo essencial fica isolado.","Os caminhos funcionam no contexto publicado.","A mesma regra não é mantida em cópias divergentes."],"challenge":[{"question":"Um arquivo foi dividido em guia e referência, mas o novo índice não liga à referência. Qual problema existe?","options":["Ter vários arquivos garante automaticamente boa descoberta.","Referências nunca precisam aparecer num índice.","Parte do conteúdo essencial ficou isolada do percurso de entrada e precisa de navegação adequada.","A extensão .md encontra sozinha qualquer arquivo relacionado."],"answer":2,"explanation":"Dividir só ajuda quando o leitor encontra o documento relevante para sua tarefa; revise índice e retornos."},{"question":"Uma seção ganhou um título com acentos e pontuação diferentes. Um link antigo ainda aponta para o fragmento presumido pelo autor. Qual ação é correta?","options":["Aplicar uma regra universal de remoção de acentos a qualquer plataforma.","Presumir que a nova seção terá obrigatoriamente o mesmo ID.","Converter todos os links externos em imagens.","Inspecionar a âncora gerada no destino e revisar os usos afetados."],"answer":3,"explanation":"A geração de IDs não é padronizada pela base CommonMark; o destino precisa ser observado."},{"question":"Um modelo de relatório com PREENCHER_ID foi publicado como entrega concluída. Qual é a falha?","options":["Uma orientação de preenchimento foi confundida com informação final verificada.","Markdown não permite letras maiúsculas.","O documento deveria executar automaticamente uma consulta à OS.","Todo placeholder tem significado operacional garantido."],"answer":0,"explanation":"Modelos e entregas finais têm papéis diferentes; os marcadores devem ser resolvidos ou apresentados claramente como pendências."}]},{"id":10,"title":"Extensões e portabilidade","tag":"Especialista","hours":6,"summary":"Use recursos extras apenas quando o ambiente oferece suporte e uma alternativa adequada.","skills":["Mermaid","Front matter","MDX e extensões"],"project":"Documento com alternativa portátil","deliverables":["Diagrama opcional acompanhado de texto equivalente.","Metadados separados do conteúdo principal.","Inventário de extensões exigidas pelo destino."],"rubric":["Mermaid e metadados não são apresentados como CommonMark.","Texto essencial continua compreensível sem extensões.","Não há dependência de execução de componentes para ler a regra principal."],"challenge":[{"question":"Um preview mostra a fonte de um diagrama Mermaid, mas os títulos e a regra em texto funcionam. O que essa observação indica?","options":["Todo o documento está necessariamente inválido.","O preview pode estar tratando a cerca como código por não ter a integração de diagrama.","A condição descrita no diagrama foi executada no sistema.","Mermaid é uma obrigação da sintaxe CommonMark."],"answer":1,"explanation":"A cerca é válida como bloco literal; a transformação em figura depende de um recurso extra do destino."},{"question":"O campo title de um front matter não apareceu no título visual de um preview comum. Qual explicação deve ser considerada?","options":["Todo campo title garante um cabeçalho visual em qualquer ambiente.","O texto do corpo deixou de ser Markdown por conter um título.","O preview pode não ter um gerador configurado para consumir aquele metadado.","A data do sistema deve sempre criar o título automaticamente."],"answer":2,"explanation":"Metadados têm um consumidor e um contrato próprios. A base Markdown não obriga que aquele campo governe a apresentação."},{"question":"Uma documentação portátil só pode ser lida se um componente MDX executar. Qual avaliação é adequada?","options":["MDX é obrigatório em qualquer arquivo .md.","Qualquer preview CommonMark executará o componente sem configuração.","O componente dispensa a descrição da regra.","Há uma dependência adicional de pipeline; a regra essencial deve ter uma alternativa adequada ao público e ao destino."],"answer":3,"explanation":"Componentes e expressões pertencem a um ambiente específico; considere o custo e a acessibilidade da dependência."}]},{"id":11,"title":"Decisões e manutenção","tag":"Especialista","hours":6,"summary":"Registre mudanças e prepare outras pessoas para revisar documentos.","skills":["Decisões","Histórico","Contribuição"],"project":"Guia de manutenção documental","deliverables":["Decisão com contexto, alternativa e consequência.","Histórico de mudanças útil para leitores.","Checklist de contribuição e revisão."],"rubric":["Decisões descrevem o que foi escolhido e por quê.","Mudanças têm efeito observável e versão ou data.","Critérios incluem conteúdo, links e renderização."],"challenge":[{"question":"Uma decisão antiga foi substituída, mas só a conclusão original continua visível sem estado ou ligação. O que melhorar?","options":["Indicar que foi substituída e ligar ao registro vigente com o contexto da mudança.","Reescrever o passado para fingir que a escolha nova sempre existiu.","Apagar qualquer explicação da mudança.","Usar apenas uma cor diferente no título antigo."],"answer":0,"explanation":"O histórico deve permitir descobrir qual decisão vale e por que o contexto levou à revisão."},{"question":"Um histórico registra Mudanças diversas para uma correção que altera a interpretação do saldo. Qual item é mais informativo?","options":["Escrever apenas mais adjetivos sobre a revisão.","Explicar a regra corrigida e o cenário afetado, mantendo o guia vigente coerente.","Listar o tamanho em bytes sem descrever o efeito.","Mover a regra ativa apenas para o histórico."],"answer":1,"explanation":"O leitor precisa compreender o impacto da alteração e encontrar o procedimento atual no lugar apropriado."},{"question":"O revisor conferiu links e números, mas não conseguiu renderizar uma extensão. Como registrar a revisão?","options":["Marcar o teste visual como concluído mesmo assim.","Concluir que todo destino terá o mesmo resultado.","Informar as verificações executadas e manter a extensão como pendência ou limite explícito.","Omitir o renderizador usado para encurtar o registro."],"answer":2,"explanation":"Uma evidência útil distingue o que foi observado daquilo que ainda precisa de conferência."}]},{"id":12,"title":"Entrega e auditoria","tag":"Especialista","hours":6,"summary":"Revise o conjunto como um produto que precisa orientar trabalho real.","skills":["Diagnóstico","Revisão","Projeto final"],"project":"Manual de OS e estoque","deliverables":["README de entrada, guia do operador e referência de estados.","Exemplo de OS, matriz de estoque e procedimento de recuperação documental.","Relatório final de revisão e limitações do renderizador."],"rubric":["Um leitor executa o percurso proposto sem explicação oral adicional.","Links, exemplos e regras são coerentes entre arquivos.","As extensões e as revisões pendentes estão declaradas."],"challenge":[{"question":"Uma lista aninhada saiu do lugar. O autor trocou recuo, tema, arquivo e editor ao mesmo tempo e o problema sumiu. Qual limite dessa investigação?","options":["Ela comprova que todos os editores antigos estão errados.","Ela prova que recuo nunca influencia listas.","Ela transforma uma hipótese em regra universal de Markdown.","Ela não permite atribuir com clareza o resultado a uma causa específica."],"answer":3,"explanation":"Alterar múltiplos fatores pode resolver o caso, mas não isola a causa. Reduza e compare de modo controlado."},{"question":"A edição CommonMark de um manual perdeu checkboxes e diagrama visual, mas preservou tarefas e regras em texto equivalente. Como avaliar a portabilidade?","options":["Verificar se as informações e ações essenciais continuam claras, distinguindo diferença visual de perda funcional.","Exigir obrigatoriamente os mesmos ícones e cores em todo destino.","Declarar falha total só porque a aparência mudou.","Ignorar links e valores porque o arquivo abre."],"answer":0,"explanation":"O contrato de portabilidade deve focar nas propriedades necessárias ao leitor, sem presumir tema ou extensões universais."},{"question":"O projeto final abre no preview, mas contém links locais inexistentes e afirma que recuperar o manual restaura o banco. O que impede a entrega?","options":["A ausência de um avatar no README.","Faltam verificar os destinos e corrigir o escopo da recuperação, que abrange documentos e não os dados da aplicação.","A existência de uma fonte de texto diferente.","A necessidade universal de converter o manual para MDX."],"answer":1,"explanation":"Entrega documental exige coerência, navegação funcional e limites precisos. Renderizar a sintaxe é apenas uma parte da verificação."}]}],"lessons":[{"id":1,"level":1,"title":"Seu primeiro arquivo e o preview","goal":"Distinguir texto-fonte, estrutura e apresentação renderizada.","theory":[{"title":"Texto continua sendo o arquivo","text":"Markdown é texto simples com sinais que descrevem estrutura. A extensão .md ajuda ferramentas a reconhecê-lo, mas não transforma o arquivo em uma aplicação. Você pode ler e editar a fonte mesmo quando não há preview disponível."},{"title":"Um renderizador interpreta a fonte","text":"O preview converte a marcação em uma apresentação, frequentemente HTML. A aparência vem também do tema e do ambiente. Dois visualizadores podem usar fontes ou espaçamentos diferentes sem mudar os mesmos blocos semânticos."},{"title":"Compare duas leituras","text":"Salve o exemplo, abra a fonte e o preview lado a lado. Identifique o título e o parágrafo nos dois. Registrar o nome do visualizador e o dialeto evita confundir uma extensão local com uma regra universal de Markdown."}],"code":"# Oficina de estudos\n\nDocumentação de um projeto didático de ordens de serviço.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um título de nível 1 e um parágrafo. Os caracteres # de marcação não aparecem no título renderizado.","quiz":{"question":"O que o preview faz com um arquivo .md?","options":["Interpreta a marcação e apresenta o conteúdo conforme um renderizador.","Executa o documento como programa Python.","Garante que qualquer link funciona.","Transforma o texto em banco de dados."],"answer":0,"explanation":"O preview mostra uma interpretação da fonte; ele não executa regras do projeto nem valida todos os destinos."},"exercises":[{"id":1,"title":"Seu documento","prompt":"Troque o título pelo nome de um projeto e escreva seu objetivo em um parágrafo.","hint":"Mantenha um espaço após #.","solution":"Use # Estoque de estudo, uma linha vazia e um objetivo curto que diga para quem o projeto serve.","criteria":["Há um título reconhecido no preview.","O objetivo pode ser entendido ao ler apenas a fonte."]},{"id":2,"title":"Fonte e resultado","prompt":"Registre duas diferenças visuais entre fonte e preview sem alterar o significado.","hint":"Observe sinais de marcação e tamanho do título.","solution":"Na fonte aparece # e uma quebra textual; no preview há um título visual e um parágrafo. O texto principal permanece igual.","criteria":["Distingue sintaxe de tema.","Não afirma que uma fonte maior acrescentou informação."]},{"id":3,"title":"Identifique o ambiente","prompt":"Anote qual editor e qual modo de Markdown foram usados.","hint":"Procure as opções ou a documentação do preview.","solution":"Registre por exemplo editor local com preview CommonMark, ou um preview GFM. Se não souber o dialeto, anote como uma informação a confirmar.","criteria":["Informa o visualizador real.","Não presume GFM apenas pela extensão .md."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":2,"level":1,"title":"Títulos, parágrafos e hierarquia","goal":"Estruturar um texto em seções que representem as partes do assunto.","theory":[{"title":"Títulos representam relações","text":"Um título ATX usa de um a seis # seguidos de espaço. O número indica nível, não uma escolha livre de tamanho de fonte. Organize seções como partes de um documento e subseções como partes da seção anterior."},{"title":"Parágrafos precisam de separação","text":"Uma linha vazia separa parágrafos. Uma simples mudança de linha dentro do mesmo parágrafo costuma ser uma quebra suave; não a use para fingir dois blocos. Separar blocos deixa a fonte mais previsível e fácil de revisar."},{"title":"Uma convenção útil","text":"Um título principal e níveis seguintes coerentes são uma boa convenção editorial, não uma limitação que o parser imponha. Evite pular níveis apenas para conseguir aparência menor. O leitor deve conseguir prever onde encontrar cada assunto."}],"code":"# Manual da oficina\n\nEste manual orienta a conferência de uma OS.\n\n## Preparação\n\nAbra os dados fictícios da aula.\n\n### Material necessário\n\nTenha o identificador da OS.\n\n## Conferência\n\nCompare os registros antes de confirmar.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um título principal, duas seções de nível 2 e uma subseção de nível 3 dentro de Preparação.","quiz":{"question":"Qual marcação cria um título ATX de nível 2?","options":["##Preparação sem espaço.","## Preparação","Preparação escrita em maiúsculas.","**Preparação** em um parágrafo."],"answer":1,"explanation":"O espaço após o marcador separa o texto do título; negrito e maiúsculas não criam esse bloco."},"exercises":[{"id":1,"title":"Nova seção","prompt":"Acrescente uma seção de Resultado no mesmo nível de Conferência.","hint":"Compare a quantidade de # das seções irmãs.","solution":"Use ## Resultado depois de uma linha vazia e um parágrafo sobre o estado final esperado.","criteria":["Resultado é uma seção de nível 2.","Há um parágrafo separado após o título."]},{"id":2,"title":"Divida o parágrafo","prompt":"Transforme duas instruções de um único parágrafo em dois parágrafos verdadeiros.","hint":"Não basta dar Enter uma vez.","solution":"Coloque uma linha vazia entre as instruções e confira que o preview mostra dois blocos de parágrafo.","criteria":["A fonte tem uma linha vazia entre blocos.","A mudança é confirmada no preview."]},{"id":3,"title":"Revise níveis","prompt":"Explique por que trocar Material necessário para ###### só para reduzir a fonte prejudica a estrutura.","hint":"Pense em relação entre seções, não no tema.","solution":"O nível passaria a declarar uma profundidade que a organização não possui. Mantenha ### e deixe apresentação para o renderizador.","criteria":["Relaciona nível com hierarquia.","Propõe uma estrutura coerente."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":3,"level":1,"title":"Ênfase e código inline","goal":"Diferenciar destaque textual de nomes e valores literais.","theory":[{"title":"Destaque tem intenção","text":"Asteriscos simples marcam ênfase e pares marcam ênfase forte em situações usuais. Escolha o que merece atenção; tornar tudo forte elimina o contraste. Pontuação e espaços ao redor dos delimitadores afetam a interpretação."},{"title":"Código inline preserva o literal","text":"Crases delimitam um trecho literal como nome de arquivo, campo ou comando. Dentro dele, sinais como * não se tornam ênfase. Use código para a forma exata que o leitor deve reconhecer, e texto normal para explicar seu significado."},{"title":"Não depende só do visual","text":"Uma condição crítica também deve estar descrita em palavras. O negrito ajuda a localizar a regra, mas leitores podem receber o documento sem o mesmo tema ou apresentação. A intenção do texto precisa sobreviver à leitura da fonte."}],"code":"# Conferência\n\n**Confira o saldo antes de confirmar.**\n\nO campo `status` deve conter `aberta`. O arquivo de exemplo é `ordem.json`.\n\nA confirmação é *uma etapa posterior* à conferência.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"A regra inicial aparece em destaque forte; status, aberta e ordem.json são literais; a frase final contém ênfase.","quiz":{"question":"Qual forma é mais adequada para mencionar literalmente o campo status?","options":["# status","> status","`status`","[status] sem destino"],"answer":2,"explanation":"Código inline distingue a grafia exata de um campo da explicação em linguagem natural."},"exercises":[{"id":1,"title":"Regra e literal","prompt":"Escreva uma frase com uma regra importante em forte e o nome saldo como código inline.","hint":"Use delimitadores diferentes para intenções diferentes.","solution":"Uma opção é **Verifique o campo `saldo` antes de confirmar.**; o campo permanece literal dentro do trecho forte.","criteria":["Há um literal saldo reconhecível.","A regra está expressa em palavras."]},{"id":2,"title":"Asterisco literal","prompt":"Mostre o texto A*B como código inline e compare com um texto sem crases.","hint":"Dentro do trecho de código não há ênfase.","solution":"Escreva `A*B` para conservar o asterisco como parte do valor. Não dependa de uma coincidência da análise de ênfase.","criteria":["O asterisco é visível.","Explica a escolha de código inline."]},{"id":3,"title":"Reduza ruído","prompt":"Revise um parágrafo que colocou todas as palavras em negrito.","hint":"Escolha apenas uma ação ou condição relevante.","solution":"Deixe a maior parte do texto normal e destaque a condição de confirmação; a estrutura deve continuar compreensível sem destaque.","criteria":["O destaque possui finalidade clara.","O significado continua legível na fonte."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":4,"level":2,"title":"Listas e procedimentos","goal":"Escolher listas ordenadas ou não ordenadas conforme a relação entre itens.","theory":[{"title":"Quando a ordem importa","text":"Uma lista ordenada comunica uma sequência: preparar, conferir e confirmar. Marcadores com número e ponto são uma forma usual. O renderizador pode numerar a sequência a partir do primeiro número; não confunda números digitados com uma validação do procedimento."},{"title":"Agrupamentos sem sequência","text":"Use uma lista de marcadores para itens de um conjunto, como materiais necessários. Hífen seguido de espaço é uma opção legível. O tipo de lista deve refletir o assunto, e não apenas a preferência visual do autor."},{"title":"Passos observáveis","text":"Cada passo deve dizer o que fazer e, quando necessário, o que conferir. Uma lista bonita com verbos vagos ainda não é um procedimento. Use linhas vazias antes do bloco para manter a fonte organizada e reduzir interpretações inesperadas em outros ambientes."}],"code":"# Conferência de OS\n\n## Antes de começar\n\n- Identificador da OS.\n- Acesso ao registro de estudo.\n\n## Passos\n\n1. Abra a OS pelo identificador.\n2. Confira o serviço e o saldo.\n3. Registre a conclusão da conferência.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Uma lista de dois materiais sem ordem e uma lista de três passos numerados.","quiz":{"question":"Para três ações que precisam ocorrer em sequência, qual estrutura é adequada?","options":["Um único bloco de código sem explicação.","Três títulos de nível 1 para simular números.","Uma imagem sem alternativa textual.","Uma lista ordenada com passos claros."],"answer":3,"explanation":"A lista ordenada explicita a sequência, mas ainda precisa de instruções e resultados compreensíveis."},"exercises":[{"id":1,"title":"Etapa ausente","prompt":"Inclua uma etapa de conferir o identificador antes de conferir saldo.","hint":"Insira a ação no ponto em que ela é necessária.","solution":"Coloque a conferência do identificador depois de abrir a OS e antes da conferência de serviço e saldo.","criteria":["A posição da etapa faz sentido.","A lista renderiza como uma sequência."]},{"id":2,"title":"Conjunto ou sequência","prompt":"Escreva uma lista de evidências que podem ser consultadas em qualquer ordem.","hint":"A relação é de conjunto.","solution":"Use marcadores para foto do equipamento, registro de instalação e observação do atendimento. Não numere como uma sequência obrigatória.","criteria":["Os itens têm relação paralela.","Explica por que a ordem é dispensável."]},{"id":3,"title":"Ação verificável","prompt":"Melhore o passo Faça a conferência.","hint":"Diga objeto e critério da ação.","solution":"Substitua por Compare o ID da OS e o serviço com o registro de atendimento; se houver divergência, registre a pendência antes de confirmar.","criteria":["A ação tem objeto claro.","Há uma condição ou resultado observável."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":5,"level":2,"title":"Aninhamento e blocos dentro de itens","goal":"Manter subitens e exemplos ligados ao item correto.","theory":[{"title":"Recuo depende do marcador","text":"Conteúdo de um item deve ser recuado até a coluna de seu conteúdo para continuar dentro dele. Não existe uma regra universal de sempre dois espaços para qualquer lista: a largura de um marcador ordenado também entra no alinhamento."},{"title":"Um item pode conter blocos","text":"Listas podem incluir parágrafos, sublistas e código. Linhas vazias e recuos influenciam os limites desses blocos. Escreva um exemplo pequeno e confira a árvore visual antes de expandir um procedimento longo."},{"title":"Escolha pouca profundidade","text":"Aninhe quando há dependência real. Muitas camadas dificultam a leitura da fonte e do preview. Se uma subtarefa possui várias etapas e resultados próprios, uma subseção com um título pode ser mais clara do que uma lista cada vez mais profunda."}],"code":"# Preparação\n\n1. Confira os dados da OS.\n   - Identificador correto.\n   - Serviço previsto.\n\n   Registre a divergência antes de continuar.\n\n2. Separe as evidências.\n   - Foto do equipamento.\n   - Registro de instalação.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Duas etapas principais; cada uma contém seus subitens. O parágrafo de divergência pertence ao primeiro item.","quiz":{"question":"Por que um subitem pode sair da lista em um preview?","options":["O recuo pode não colocá-lo dentro do conteúdo do item pai.","Porque listas nunca aceitam outras listas.","Porque todo item precisa ser um título.","Porque Markdown ordena os itens alfabeticamente."],"answer":0,"explanation":"O parser usa marcadores e recuo para determinar a relação entre blocos; observe a coluna do conteúdo do item pai."},"exercises":[{"id":1,"title":"Subitem correto","prompt":"Acrescente uma conferência de data como subitem da primeira etapa.","hint":"Alinhe o marcador com os demais subitens.","solution":"Insira três espaços antes de - Data do atendimento no exemplo, preservando o alinhamento dos subitens daquela lista ordenada.","criteria":["Data aparece dentro da etapa 1.","Não vira uma terceira etapa principal."]},{"id":2,"title":"Parágrafo solto","prompt":"Remova o recuo do parágrafo de divergência e explique a mudança no preview.","hint":"Compare o pertencimento do bloco.","solution":"Sem o recuo, ele deixa de estar claramente dentro do primeiro item. Restaure o alinhamento para manter a instrução ligada à etapa.","criteria":["Registra a mudança observada.","Restaura o pertencimento correto."]},{"id":3,"title":"Reduza profundidade","prompt":"Reorganize uma lista com cinco camadas em duas subseções e listas curtas.","hint":"Cada subtarefa maior pode ganhar um título.","solution":"Separe Preparar dados e Conferir evidências em seções e mantenha apenas os itens diretamente relacionados a cada uma.","criteria":["A organização mantém todas as ações.","A fonte fica mais fácil de percorrer."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":6,"level":2,"title":"Citações e separadores","goal":"Representar texto citado e mudanças de assunto sem confundir instrução com citação.","theory":[{"title":"Citação é um tipo de conteúdo","text":"O sinal > cria um bloco de citação. Ele pode conter outros blocos, mas não significa automaticamente aviso, dica ou erro. Se você o usar como convenção editorial para uma observação, explique a intenção com palavras."},{"title":"Atribua quando for citação","text":"Ao reproduzir fala ou texto de outra fonte, identifique quem disse e onde conferir. Nos exemplos da trilha os registros são fictícios. Um marcador visual de citação não prova que o texto citado é correto ou ainda está atualizado."},{"title":"Separadores não substituem títulos","text":"Uma linha temática pode separar partes visualmente. Uma linha com três hífens pode ter outras interpretações dependendo do contexto, como um título Setext após texto. Use linhas vazias e confira o bloco resultante, priorizando títulos descritivos para navegação."}],"code":"# Registro de conferência\n\n## Observação recebida\n\n> Registro fictício do operador: o equipamento já consta como instalado.\n\nA equipe deve conferir as evidências antes de confirmar a OS.\n\n---\n\n## Próximo passo\n\nRegistre a decisão e a justificativa.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Uma observação em bloco de citação, uma instrução normal e um separador antes da seção seguinte.","quiz":{"question":"O marcador > garante que um texto é uma instrução obrigatória?","options":["Sim, ele valida juridicamente a instrução.","Não; ele cria uma citação, e a função editorial precisa ser expressa no conteúdo.","Sim, ele transforma qualquer frase em checklist.","Não, porque > é sempre texto literal."],"answer":1,"explanation":"A estrutura de citação não determina o grau de obrigatoriedade nem verifica a origem da afirmação."},"exercises":[{"id":1,"title":"Dê contexto","prompt":"Acrescente uma segunda frase à citação mantendo claro que ela vem do registro fictício.","hint":"Use o marcador nas linhas citadas.","solution":"Acrescente > O atendimento foi realizado no turno da manhã. e mantenha a atribuição ao registro de exemplo.","criteria":["A segunda frase está no mesmo bloco citado.","A origem fictícia continua explícita."]},{"id":2,"title":"Obrigação visível","prompt":"Reescreva uma regra essencial que estava escondida numa citação sem título.","hint":"Diga diretamente quem deve fazer o quê.","solution":"Coloque a regra no texto principal sob um título como Conferência obrigatória e descreva a condição para confirmar.","criteria":["A obrigação é expressa em palavras.","A citação deixa de ser o único lugar da regra."]},{"id":3,"title":"Separe blocos","prompt":"Teste três hífens imediatamente abaixo de uma palavra e depois com uma linha vazia antes.","hint":"O contexto pode formar um título Setext.","solution":"Sem linha vazia, a linha pode participar de um título; com separação, os hífens funcionam como linha temática naquele contexto.","criteria":["Compara os dois previews.","Explica o papel da linha vazia."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":7,"level":3,"title":"Blocos cercados e linguagem de exemplo","goal":"Exibir vários comandos ou linhas de código sem executá-los.","theory":[{"title":"Cerca delimita o conteúdo","text":"Uma cerca de pelo menos três crases ou tils abre um bloco de código. O fechamento precisa usar o mesmo tipo de caractere e ter comprimento suficiente. O conteúdo é literal, não um conjunto de instruções executadas pelo preview."},{"title":"Identificador auxilia o realce","text":"Uma palavra após a cerca, como json ou text, pode orientar o realce. O suporte depende do ambiente e do identificador. Cores não validam a sintaxe ou o comportamento de um programa; o exemplo deve declarar o que representa."},{"title":"Contexto e resultado","text":"Diga se o trecho é comando, entrada ou saída. Misturar tudo numa cerca pode fazer o leitor copiar o prompt e a resposta como se fossem comandos. Separe os blocos e use dados pequenos cuja finalidade seja fácil de explicar."}],"code":"# Exemplo de uma ordem\n\nA entrada abaixo é um registro fictício, não um comando.\n\n```json\n{\"id\":\"OS-1\",\"status\":\"aberta\"}\n```\n\nO relatório apresenta o identificador e o estado:\n\n```text\nOS-1 aberta\n```\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Dois blocos de código: um JSON de entrada e um texto de saída, com explicações fora das cercas.","quiz":{"question":"Adicionar json após uma cerca garante que o JSON é válido?","options":["Sim, o preview rejeita qualquer erro de contrato.","Sim, o bloco é enviado a um banco automaticamente.","Não; o identificador pode orientar realce, mas não é validação.","Não, porque a cerca remove o conteúdo."],"answer":2,"explanation":"Um renderizador pode aplicar cores sem executar ou validar o exemplo."},"exercises":[{"id":1,"title":"Entrada e saída","prompt":"Escreva um exemplo de saldo em JSON e sua saída textual em blocos separados.","hint":"Descreva a função de cada bloco.","solution":"Use um bloco json com {\"saldo\":3} e outro text com Saldo disponível: 3, separados por explicações.","criteria":["Os blocos estão fechados corretamente.","Entrada e saída não são confundidas."]},{"id":2,"title":"Fechamento perdido","prompt":"Remova a cerca final do primeiro bloco e observe o que passa a ser mostrado como código.","hint":"A ausência afeta o conteúdo seguinte.","solution":"O bloco pode continuar até outra cerca compatível ou até o fim do documento. Restaure o fechamento no lugar correto.","criteria":["Registra o efeito no texto seguinte.","Corrige o limite do bloco."]},{"id":3,"title":"Comando copiável","prompt":"Crie uma instrução com um comando fictício sem incluir o prompt do terminal no trecho copiável.","hint":"Prompt e resultado devem ficar fora do comando.","solution":"Descreva que o comando é ilustrativo e coloque apenas oficina conferir OS-1 numa cerca text; a saída deve ter outro bloco.","criteria":["Não inclui caracteres de prompt como parte do comando.","Declara que o comando é ilustrativo."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-and-highlighting-code-blocks","caution":"","local":true,"hours":2,"minutes":45},{"id":8,"level":3,"title":"Crases, escapes e exemplos de Markdown","goal":"Mostrar sintaxe de Markdown como conteúdo literal.","theory":[{"title":"Delimitador maior protege o exemplo","text":"Para mostrar uma cerca de três crases dentro de um bloco, use uma cerca externa maior, ou outra forma válida de delimitação. É o fechamento compatível que define o limite; simplesmente colar três crases por toda parte pode encerrar o bloco cedo."},{"title":"Código inline pode conter crases","text":"Uma sequência de crases pode delimitar código inline que contém uma sequência menor. Quando espaços são usados para separar os delimitadores do conteúdo, as regras de normalização precisam ser consideradas. Verifique a forma renderizada e o texto copiado."},{"title":"Escape é contextual","text":"Uma barra invertida pode escapar pontuação elegível fora de blocos literais. Dentro de código o objetivo costuma ser mostrar os caracteres exatos, sem acrescentar barras desnecessárias. Não aplique escape indiscriminadamente a todo o documento."}],"code":"# Sintaxe como exemplo\n\nO texto \\*pendente\\* deve mostrar os asteriscos.\n\nO trecho `` `status` `` mostra crases no conteúdo inline.\n\n````markdown\n# Mini guia\n\n```text\nOS-1 aberta\n```\n````\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Asteriscos literais em *pendente*, um trecho inline com crases visíveis e um bloco que mostra um pequeno arquivo Markdown sem fechar cedo.","quiz":{"question":"Como mostrar uma cerca de três crases dentro de um bloco cercado por crases?","options":["Use exatamente três crases para todos os limites.","Remova todas as linhas vazias do documento.","Transforme o conteúdo em um título de nível 6.","Use uma cerca externa mais longa e um fechamento compatível."],"answer":3,"explanation":"Uma cerca interna menor permanece conteúdo quando a cerca externa exige um fechamento mais longo."},"exercises":[{"id":1,"title":"Exemplo de tabela literal","prompt":"Mostre a fonte de uma pequena tabela GFM sem transformá-la em tabela na aula.","hint":"Uma cerca markdown mantém o conteúdo literal.","solution":"Coloque o cabeçalho, o separador e uma linha de dados dentro de uma cerca markdown com fechamento próprio.","criteria":["A fonte da tabela aparece como código.","Os delimitadores não desaparecem no preview."]},{"id":2,"title":"Asteriscos de nome","prompt":"Escreva um identificador A*B fora de código e decida como preservar sua forma.","hint":"Você pode usar código inline para um identificador literal.","solution":"Use `A*B`; se o objetivo for texto normal com asteriscos, teste os escapes adequados. O significado do conteúdo orienta a escolha.","criteria":["A grafia literal é preservada.","Explica por que escolheu código ou escape."]},{"id":3,"title":"Cerca aninhada","prompt":"Mostre num documento um exemplo de Markdown que contém uma cerca json.","hint":"A cerca externa precisa proteger a interna.","solution":"Use quatro crases fora e três dentro, sem inserir um fechamento externo antes do fim do exemplo.","criteria":["O exemplo completo fica no mesmo bloco.","Há correspondência entre abertura e fechamento."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":9,"level":3,"title":"Quebras de linha e espaços significativos","goal":"Distinguir parágrafos, quebras suaves e quebras forçadas.","theory":[{"title":"Uma linha não é sempre um parágrafo","text":"Uma quebra comum dentro de um parágrafo é uma quebra suave em CommonMark. O renderizador pode apresentá-la como espaço ou quebra visual. Se você precisa de dois parágrafos, use uma linha vazia em vez de depender do tema."},{"title":"Quebra forçada é uma decisão","text":"Duas ou mais posições de espaço no final de uma linha, ou uma barra invertida antes da quebra, podem produzir uma quebra forçada fora dos contextos literais. Espaços finais são difíceis de ver e podem ser removidos por ferramentas; a barra fica explícita na fonte."},{"title":"Escreva para manutenção","text":"Quebrar a fonte em linhas curtas pode facilitar revisão, mas a formatação não deve depender de espaços invisíveis sem necessidade. Use quebras forçadas para casos como endereço ou verso, e parágrafos para unidades de ideia."}],"code":"# Registro curto\n\nA OS foi conferida\ne segue para revisão.\n\nResponsável: equipe de estudo\\\nTurno: manhã\n\nEste é outro parágrafo.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"O primeiro bloco é um parágrafo com quebra suave; Responsável e Turno têm uma quebra forçada; o último texto é um parágrafo separado.","quiz":{"question":"Qual forma comunica dois parágrafos distintos de modo explícito?","options":["Uma linha vazia entre os textos.","Um espaço no meio de uma palavra.","Uma única quebra suave obrigatoriamente em todos os renderizadores.","Uma mudança na largura da janela."],"answer":0,"explanation":"A linha vazia separa blocos de parágrafo; quebra suave e largura visual não equivalem a essa estrutura."},"exercises":[{"id":1,"title":"Duas ideias","prompt":"Divida um parágrafo de preparação e conclusão em dois parágrafos.","hint":"Separe blocos com linha vazia.","solution":"Mantenha uma unidade de ideia em cada parágrafo e confira que ambos continuam distintos em janelas de larguras diferentes.","criteria":["Há dois blocos de parágrafo.","A divisão acompanha as ideias."]},{"id":2,"title":"Quebra visível","prompt":"Troque a barra invertida do exemplo por dois espaços finais e compare a manutenção da fonte.","hint":"Ative a exibição de espaços do editor se disponível.","solution":"O resultado pode ser equivalente, mas a fonte com espaços finais exige cuidado para não perdê-los em formatação automática.","criteria":["Confere o resultado real.","Identifica o risco de espaços invisíveis."]},{"id":3,"title":"Preview diferente","prompt":"Explique por que dois previews podem apresentar diferente a quebra suave sem que ambos estejam errados.","hint":"Considere o contrato da quebra suave.","solution":"CommonMark permite apresentá-la como espaço ou quebra. Para exigir separação semântica, use parágrafos; para linha forçada, use a sintaxe correspondente.","criteria":["Não confunde tema com estrutura.","Escolhe a sintaxe conforme a intenção."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":10,"level":4,"title":"Links com rótulos que explicam o destino","goal":"Criar links inline compreensíveis e diferenciar texto, destino e título opcional.","theory":[{"title":"Rótulo é parte da orientação","text":"Um link inline combina o texto entre colchetes e um destino entre parênteses. O rótulo precisa fazer sentido quando o leitor busca um assunto ou percorre uma lista de links. Prefira Consultar a especificação a um clique aqui sem contexto."},{"title":"Destino não é o texto visível","text":"Você pode trocar o rótulo sem trocar o endereço, e o contrário também. Confira ambos: um rótulo correto apontando para a página errada continua sendo um erro documental. Um título opcional de link não substitui o texto principal nem deve esconder informação essencial."},{"title":"Abra o destino com intenção","text":"Use endereços completos para recursos externos e evite parâmetros pessoais ou tokens em exemplos. Destinos com espaços e parênteses exigem atenção à sintaxe; caminhos simples com nomes previsíveis reduzem problemas de manutenção."}],"code":"# Referências da oficina\n\nConsulte a [especificação CommonMark](https://spec.commonmark.org/0.31.2/) para conferir a sintaxe básica.\n\nA [página de exemplo](https://example.com \"Destino usado apenas para demonstração\") não pertence ao sistema da oficina.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Dois links com textos descritivos. O segundo possui um título opcional; o documento não exige que o leitor veja esse título para entender o destino.","quiz":{"question":"O rótulo de um link deveria fazer o quê?","options":["Esconder o destino com texto aleatório.","Descrever o destino ou a ação de forma compreensível.","Ser sempre clique aqui.","Conter obrigatoriamente a URL inteira."],"answer":1,"explanation":"O rótulo ajuda a navegação; a URL precisa ser conferida separadamente."},"exercises":[{"id":1,"title":"Rótulo melhor","prompt":"Troque um link clique aqui para saber das regras por um rótulo que nomeie o destino.","hint":"Use a parte que informa o assunto como rótulo.","solution":"Escreva [Consultar as regras de confirmação](https://example.com) e declare que o endereço é ilustrativo no exercício.","criteria":["O rótulo descreve as regras.","Não trata o endereço ilustrativo como sistema real."]},{"id":2,"title":"Destino diferente","prompt":"Crie dois links com o mesmo destino CommonMark e rótulos adequados a frases diferentes.","hint":"A sintaxe permite separar texto e URL.","solution":"Use especificação da sintaxe em uma frase e consultar CommonMark em outra, ambos apontando para a especificação correta.","criteria":["Ambos os destinos estão completos.","Os rótulos fazem sentido no contexto."]},{"id":3,"title":"Título dispensável","prompt":"Remova o título opcional do segundo link e explique o que precisa continuar compreensível.","hint":"O leitor pode não receber o mesmo comportamento de tooltip.","solution":"O texto página de exemplo e a frase que explica sua função devem bastar. Uma informação indispensável não deveria ficar apenas no título opcional.","criteria":["O sentido não depende do título opcional.","O link continua sintaticamente completo."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":11,"level":4,"title":"Links por referência e definições reutilizáveis","goal":"Separar o fluxo do texto de endereços repetidos sem criar referências ambíguas.","theory":[{"title":"Uma definição concentra o endereço","text":"Links por referência usam um rótulo de referência para encontrar uma definição em outra parte do documento. Isso pode reduzir repetição de URLs longas e facilitar atualização. A definição é parte da fonte e normalmente não aparece como um parágrafo do preview."},{"title":"Referências precisam resolver","text":"O rótulo no uso e o rótulo na definição precisam corresponder segundo as regras de normalização do parser. Use nomes simples, exclusivos e relacionados ao assunto. Uma referência não resolvida pode aparecer como texto literal em vez de virar um link."},{"title":"Atualização com revisão","text":"Concentrar a URL não elimina a obrigação de conferir se todos os usos ainda descrevem o destino. Se uma definição passa a apontar para outro assunto, rótulos antes corretos podem ficar enganosos. Não reutilize uma mesma referência para significados diferentes."}],"code":"# Fontes de consulta\n\nA [base de sintaxe][commonmark] descreve os blocos do documento.\n\nConsulte a [mesma especificação][commonmark] quando houver dúvida de interpretação.\n\n[commonmark]: https://spec.commonmark.org/0.31.2/ \"Especificação de referência\"\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Dois links apontam para a mesma definição; a linha de definição não aparece como texto comum na apresentação.","quiz":{"question":"Se um rótulo de referência não possui definição correspondente, o que pode acontecer?","options":["O preview descobre automaticamente qualquer URL desejada.","O documento sempre deixa de abrir.","A marcação permanece texto em vez de se tornar o link pretendido.","O link passa obrigatoriamente a apontar para a pasta pai."],"answer":2,"explanation":"A definição é necessária para resolver aquela forma de link; o renderizador não adivinha o endereço."},"exercises":[{"id":1,"title":"Segunda fonte","prompt":"Adicione uma definição gfm e use-a numa frase sobre extensões.","hint":"Mantenha nomes exclusivos por fonte.","solution":"Use [extensões GFM][gfm] e defina [gfm]: https://github.github.com/gfm/ no fim.","criteria":["A referência resolve no preview.","As duas fontes têm rótulos diferentes."]},{"id":2,"title":"Referência quebrada","prompt":"Troque um uso commonmark por commonmar e observe o resultado antes de corrigir.","hint":"Procure a definição exata na fonte.","solution":"O uso sem definição tende a permanecer literal; restaure o rótulo correto, sem duplicar endereços desnecessariamente.","criteria":["Registra o erro observado.","A correção preserva a definição única."]},{"id":3,"title":"Uso enganoso","prompt":"Explique o problema de chamar uma referência de tutorial de estoque quando ela aponta para a especificação CommonMark.","hint":"Sintaxe correta não garante conteúdo correto.","solution":"O destino pode estar tecnicamente válido e ainda assim contradizer o rótulo. Corrija o texto ou escolha o endereço apropriado.","criteria":["Distingue validade sintática de precisão editorial.","Propõe uma correção de sentido."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":12,"level":4,"title":"Caminhos relativos, fragmentos e contexto","goal":"Planejar links entre arquivos e seções a partir da localização do documento.","theory":[{"title":"O ponto de partida importa","text":"Um caminho relativo é resolvido a partir de um contexto fornecido pelo ambiente. Em um conjunto de arquivos no mesmo diretório, GUIA.md costuma indicar o arquivo vizinho. Quando o documento muda de pasta ou de publicação, o mesmo texto de caminho pode ganhar outro significado."},{"title":"Navegação dentro da página","text":"Um fragmento após # pode indicar uma seção. A criação automática de identificadores a partir de títulos não é definida por CommonMark; é comportamento do renderizador. Acentos, pontuação, repetições e títulos renomeados exigem verificação no destino usado."},{"title":"Monte a árvore antes do índice","text":"Decida onde ficam README, guias e imagens. Depois confira os links começando de cada arquivo, não apenas do diretório raiz. Um caminho que existe no seu computador pode falhar numa publicação com regras diferentes de nomes e maiúsculas."}],"code":"# Índice de estudo\n\nEste arquivo deve ficar ao lado de `GUIA.md`.\n\n- [Abrir o guia](GUIA.md).\n- [Conferência no guia](GUIA.md#conferencia).\n- [Limitações deste índice](#limitacoes).\n\n## Limitacoes\n\nOs fragmentos deste exemplo seguem a geração usual de títulos no GitHub. Confira no seu preview.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Para testar todos os destinos, crie GUIA.md ao lado com o título ## Conferencia. Abra no preview que permita navegação entre arquivos e confira os fragmentos reais.","expected":"No renderizador GitHub, o link interno leva a Limitacoes. Os links a GUIA.md só podem abrir se o arquivo vizinho existir e contiver o título esperado.","quiz":{"question":"Quem define de modo geral o identificador automático de um título para usar num fragmento?","options":["A extensão .md determina uma regra única em qualquer sistema.","O nome do usuário sempre vira o identificador.","O primeiro link do arquivo escolhe todos os fragmentos.","O renderizador ou ambiente, e não a base CommonMark."],"answer":3,"explanation":"CommonMark define títulos e links, mas não padroniza a política de IDs gerados para cabeçalhos."},"exercises":[{"id":1,"title":"Arquivo vizinho","prompt":"Crie GUIA.md ao lado do README com o título ## Conferencia e teste os dois primeiros links.","hint":"A existência do arquivo é uma dependência do exemplo.","solution":"O primeiro link deve abrir o arquivo e o segundo deve alcançar a seção se o preview der suporte àquele fragmento. Registre a política real.","criteria":["O arquivo vizinho foi criado.","O teste distingue abertura do arquivo e navegação da seção."]},{"id":2,"title":"Guia movido","prompt":"Mova GUIA.md para uma pasta docs e atualize os links do README.","hint":"O caminho deve incluir a nova pasta.","solution":"Use docs/GUIA.md e docs/GUIA.md#conferencia a partir do README na raiz. Depois confira também os links que partem do guia.","criteria":["Os dois links usam o contexto da raiz.","Não presume que links de retorno usam o mesmo caminho."]},{"id":3,"title":"Título renomeado","prompt":"Altere Conferencia para Conferência final e descubra a nova âncora gerada pelo seu destino.","hint":"Use o link da seção oferecido pelo visualizador, quando disponível.","solution":"Não deduza uma regra universal para acentos e espaços. Confira o ID gerado e atualize todos os usos relevantes.","criteria":["Registra a âncora observada.","Revisa os links que dependiam do título antigo."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax","caution":"","local":true,"hours":2,"minutes":45},{"id":13,"level":5,"title":"Imagens e texto alternativo","goal":"Inserir uma imagem com alternativa textual adequada ao seu papel.","theory":[{"title":"Uma imagem tem função no documento","text":"A forma ![alternativa](destino) distingue imagem de link comum. O destino precisa existir e poder ser carregado pelo ambiente. Uma imagem faltante não é corrigida por Markdown; caminhos, permissões e disponibilidade do recurso continuam sendo dependências."},{"title":"Alternativa descreve o que importa","text":"O texto alternativo deve transmitir a informação relevante, não apenas dizer imagem. Uma figura complexa pode exigir também uma descrição no texto principal. Se uma imagem é puramente decorativa, a alternativa vazia pode ser adequada, desde que a informação não dependa dela."},{"title":"Não esconda a regra na figura","text":"Diagramas e capturas ajudam a orientar, mas o leitor ainda precisa entender o procedimento sem conseguir enxergá-los. O exemplo descreve o saldo no texto e prevê uma imagem local a ser produzida durante o exercício; não há imagem anexada automaticamente."}],"code":"# Situação do estoque\n\nO item A tem 3 unidades disponíveis no exemplo. A confirmação de uma OS que usa 2 unidades deixa 1 disponível.\n\n![Exemplo de estoque: item A passa de 3 para 1 unidade após usar 2](imagens/saldo.png)\n\nA figura deve representar os mesmos números do texto.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"O texto principal informa os números mesmo sem imagem. A figura aparece quando imagens/saldo.png é fornecida; sem ela, o destino não será carregado.","quiz":{"question":"Qual alternativa é mais útil para uma figura que demonstra saldo de 3 para 1 após uma baixa de 2?","options":["Uma descrição que comunica essa mudança e os valores relevantes.","Apenas a palavra imagem.","O caminho completo do disco do autor.","Uma frase que contradiz os números do texto."],"answer":0,"explanation":"A alternativa deve servir ao papel informativo da figura; a descrição no texto principal também ajuda figuras complexas."},"exercises":[{"id":1,"title":"Produza o recurso","prompt":"Crie uma figura simples com os valores do exemplo e salve como imagens/saldo.png.","hint":"O caminho é relativo à pasta do README.","solution":"Mantenha o arquivo na pasta imagens ao lado do README e confira o carregamento no preview. Pode ser uma captura de uma tabela didática sem dados pessoais.","criteria":["O arquivo existe no caminho indicado.","A figura representa os mesmos valores do texto."]},{"id":2,"title":"Alternativa específica","prompt":"Substitua o texto alternativo figura1 por uma descrição útil de um fluxo de conferência.","hint":"Descreva a relação que a figura pretende explicar.","solution":"Uma opção é OS aberta segue para conferência de evidências; uma pendência mantém a OS aberta. Acrescente texto principal se a figura tiver muitos ramos.","criteria":["A alternativa comunica informação relevante.","Não depende de expressões como veja a cor verde."]},{"id":3,"title":"Imagem ausente","prompt":"Renomeie temporariamente a figura e confirme o que continua compreensível no documento.","hint":"O texto principal não deve perder a regra.","solution":"O carregamento falha, mas os saldos e a ação continuam explicados no parágrafo. Restaure o nome depois do teste.","criteria":["Identifica a falha do recurso.","Confirma que a regra continua disponível em texto."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":14,"level":5,"title":"Conteúdo acessível e linguagem de orientação","goal":"Revisar títulos, rótulos e instruções para leitura além da aparência visual.","theory":[{"title":"Estrutura ajuda a navegação","text":"Títulos descritivos permitem percorrer um documento por assunto. Listas organizam conjuntos e procedimentos. Não escolha uma estrutura apenas para ganhar recuo ou fonte maior; o papel do bloco deve corresponder ao conteúdo que ele contém."},{"title":"Rótulos precisam de contexto suficiente","text":"Um link chamado baixar pode ser ambíguo quando há vários arquivos. Nomeie o tipo de recurso e sua finalidade. Da mesma forma, uma imagem de status precisa de informação textual; cor sozinha não comunica a condição para todos os leitores."},{"title":"Markdown ajuda, mas não certifica","text":"A sintaxe pode gerar HTML bem estruturado, porém a acessibilidade do resultado também depende do renderizador, do tema e dos recursos externos. Revise o conteúdo e teste a apresentação real. Não declare um documento acessível só porque ele abre sem erro."}],"code":"# Conferir uma ordem\n\n## Identificar pendências\n\nUma OS com evidência ausente permanece **pendente de conferência**. O estado deve ser escrito por extenso, mesmo quando o sistema também usa uma cor.\n\n## Consultar a regra\n\nLeia a [especificação da sintaxe usada neste guia](https://spec.commonmark.org/0.31.2/).\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"O assunto de cada seção é descritivo; o estado está em palavras e o link descreve seu destino.","quiz":{"question":"Um documento usa apenas um círculo vermelho para informar uma pendência. O que melhorar?","options":["Deixar o círculo ainda menor.","Acrescentar uma indicação textual clara do estado e do que fazer.","Usar apenas uma tonalidade diferente.","Converter todos os títulos em imagens."],"answer":1,"explanation":"A informação precisa sobreviver a diferenças de visão, tema e disponibilidade da imagem."},"exercises":[{"id":1,"title":"Rótulos distintos","prompt":"Reescreva dois links chamados baixar para diferenciar guia e modelo de OS.","hint":"Nomeie o documento que será aberto.","solution":"Use Baixar o guia de conferência e Baixar o modelo de OS, com destinos apropriados no conjunto documental.","criteria":["Os rótulos distinguem os recursos.","Os nomes correspondem aos destinos."]},{"id":2,"title":"Estado em palavras","prompt":"Escreva uma indicação de saldo insuficiente que não dependa de cor.","hint":"Inclua condição e próximo passo.","solution":"Use Saldo insuficiente: há 1 unidade e a OS exige 2. Registre a pendência e não confirme a baixa.","criteria":["Informa a diferença de quantidade.","Explica a ação seguinte."]},{"id":3,"title":"Revisão estrutural","prompt":"Leia só os títulos do exemplo e descreva o caminho que eles oferecem.","hint":"Um índice deve dar pistas da tarefa.","solution":"Os títulos indicam identificar pendências e consultar uma regra. Se houvesse apenas Geral e Outros, seria necessário torná-los específicos.","criteria":["Relaciona títulos com tarefas.","Sugere títulos úteis em vez de apenas tamanhos visuais."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax","caution":"","local":true,"hours":2,"minutes":45},{"id":15,"level":5,"title":"Relatórios com fatos, limites e próximos passos","goal":"Montar um relatório que separa observação, interpretação e decisão.","theory":[{"title":"Relate o que foi observado","text":"Um relatório útil identifica o objeto, o momento e o escopo da observação. Números e estados devem ser rastreáveis ao cenário descrito. Dados didáticos precisam ser reconhecidos como fictícios para não parecerem registros operacionais reais."},{"title":"Separe evidência de conclusão","text":"Uma foto existente não prova sozinha que toda regra de um atendimento foi cumprida. Escreva a evidência disponível e o que foi concluído a partir dela. Quando algo não foi conferido, uma seção de limites é mais honesta que uma afirmação ampla."},{"title":"Termine em uma ação concreta","text":"Liste quem deve agir ou qual revisão falta, sem espalhar decisões contraditórias. Os recursos básicos de Markdown são suficientes para um relatório consistente: títulos, parágrafos, listas e literais para identificadores."}],"code":"# Relatório da OS-1\n\nCenário fictício de estudo. Revisão: 23/10/2026.\n\n## Observações\n\n- O registro da OS está com `status` igual a `aberta`.\n- A imagem de instalação foi anexada ao cenário.\n- O item A possui saldo 3 e a OS solicita 2.\n\n## Limites\n\nA autenticidade da evidência não foi verificada neste exercício.\n\n## Próximo passo\n\nConferir a evidência e registrar a decisão antes de confirmar a baixa.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um relatório com três observações, um limite explícito e uma próxima ação; ele não declara a OS concluída.","quiz":{"question":"Qual frase distingue melhor o escopo observado de uma conclusão ainda não verificada?","options":["Tudo está validado porque há um arquivo.","A OS está paga porque o Markdown foi renderizado.","A evidência foi anexada, mas sua autenticidade não foi conferida neste exercício.","O saldo foi conferido em todos os sistemas possíveis."],"answer":2,"explanation":"A frase registra o fato conhecido e seu limite, sem transformar disponibilidade de arquivo em garantia ampla."},"exercises":[{"id":1,"title":"Fato ou inferência","prompt":"Classifique a foto existe e a instalação está correta como observação ou conclusão, justificando o contexto.","hint":"Uma conclusão pode precisar de conferências adicionais.","solution":"A existência do arquivo pode ser observada; afirmar correção exige critérios e verificação que o relatório deve descrever.","criteria":["Distingue fato de inferência.","Aponta a evidência ou conferência necessária."]},{"id":2,"title":"Pendência rastreável","prompt":"Acrescente uma pendência sobre legibilidade da imagem com próximo passo.","hint":"Evite termos vagos como resolver depois.","solution":"Escreva que o identificador não está legível e que é necessário solicitar uma imagem legível antes de confirmar.","criteria":["A pendência tem motivo concreto.","A ação mantém a decisão coerente."]},{"id":3,"title":"Consistência numérica","prompt":"Se a OS passar a solicitar 4 unidades, revise o relatório.","hint":"O saldo 3 não atende ao novo consumo.","solution":"Atualize a quantidade solicitada e registre saldo insuficiente; não mantenha uma conclusão de confirmação baseada na versão anterior.","criteria":["Todos os valores relacionados foram revistos.","A decisão respeita o novo cenário."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":16,"level":6,"title":"Tabelas GFM para comparações pequenas","goal":"Organizar dados tabulares sem forçar parágrafos longos dentro de células.","theory":[{"title":"Tabela é uma extensão","text":"Tabelas com barras verticais e linha de separação são um recurso GFM, não um bloco da base CommonMark. Declare o dialeto do destino. Um preview sem essa extensão pode mostrar as linhas como texto, ainda que você tenha escrito um exemplo válido para GFM."},{"title":"Cabeçalho e colunas","text":"A primeira linha nomeia colunas e a segunda estabelece o separador. Dois pontos podem indicar alinhamento. Escolha cabeçalhos que expliquem valores e unidades; linhas curtas e paralelas tornam a tabela útil no preview e legível na fonte."},{"title":"Caracteres e limites","text":"Uma barra vertical no conteúdo precisa ser escapada conforme o dialeto, inclusive em casos dentro de código inline em tabelas GFM. Tabelas não são o melhor lugar para vários parágrafos ou procedimentos longos. Nesses casos, use seções e listas."}],"code":"# Matriz de estados\n\n| Estado | Pode confirmar? | Saldo usado |\n| --- | :---: | ---: |\n| Aberta sem conferência | Não | 0 |\n| Conferida com saldo | Sim | 2 |\n| Pendente de evidência | Não | 0 |\n\nOs valores são fictícios. A coluna Saldo usado indica o efeito da confirmação permitida.\n","filename":"README.md","language":"markdown","run":"Salve como README.md e abra num preview com tabelas GFM habilitadas. Compare também com um preview CommonMark sem extensões.","expected":"Em GFM, uma tabela de três colunas e três linhas de dados; a coluna central é marcada para centralização e a última para alinhamento à direita.","quiz":{"question":"Uma tabela GFM exige qual parte estrutural depois do cabeçalho?","options":["Uma cerca mermaid obrigatória.","Uma imagem de fundo.","Um programa que calcula o saldo.","Uma linha de separação com marcadores válidos por coluna."],"answer":3,"explanation":"O separador identifica a estrutura da tabela; os dois pontos podem orientar alinhamento, mas não executam cálculos."},"exercises":[{"id":1,"title":"Coluna de ação","prompt":"Acrescente uma coluna Próximo passo mantendo três linhas de dados.","hint":"Cada linha precisa corresponder ao cabeçalho revisado.","solution":"Inclua Conferir, Confirmar e Solicitar evidência, com os separadores necessários. Confira que não surgiu uma coluna vazia inesperada.","criteria":["O cabeçalho possui quatro colunas.","Todas as linhas mantêm a relação entre estado e ação."]},{"id":2,"title":"Barra no valor","prompt":"Mostre o literal A|B dentro de uma célula sem criar outra coluna.","hint":"Em GFM, a barra vertical precisa ser escapada dentro da célula.","solution":"Use `A\\|B` na fonte da célula e confira o texto A|B no preview com o número de colunas preservado.","criteria":["A célula mostra a barra.","Não cria uma coluna adicional."]},{"id":3,"title":"Troque o formato","prompt":"Reescreva uma célula com cinco frases e vários passos como uma seção fora da tabela.","hint":"A tabela deve comparar itens, não conter um manual inteiro.","solution":"Deixe na célula um resumo ou link descritivo e mova o procedimento para uma seção com passos numerados.","criteria":["A tabela fica comparável e curta.","O procedimento continua completo fora dela."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/organizing-information-with-tables","caution":"","local":true,"hours":2,"minutes":45},{"id":17,"level":6,"title":"Listas de tarefas e registros de revisão","goal":"Representar itens concluídos ou pendentes sem confundir documento com automação.","theory":[{"title":"Uma extensão visual","text":"Itens como - [ ] e - [x] formam listas de tarefas no GFM. O marcador precisa da estrutura correta, inclusive espaços. Em outros visualizadores, os colchetes podem permanecer texto; isso não torna o documento ilegível se os rótulos forem claros."},{"title":"Marcar não prova execução","text":"Uma caixa marcada registra uma afirmação documental. Ela não executa a conferência de uma OS nem comprova que um teste foi feito. Vincule cada item a uma evidência ou critério e revise a afirmação quando a situação mudar."},{"title":"Use tarefas pequenas","text":"Itens com várias ações dificultam saber o que falta. Separe revisar links, conferir exemplos e validar o resultado visual. Uma lista de tarefas pode acompanhar a revisão, mas não substitui a descrição do procedimento que será avaliado."}],"code":"# Revisão do guia\n\nLista de tarefas GFM para o responsável pela documentação.\n\n- [x] Identificar o público do guia.\n- [x] Conferir os valores do exemplo OS-1.\n- [ ] Abrir todos os links locais.\n- [ ] Conferir o preview no destino de publicação.\n","filename":"README.md","language":"markdown","run":"Salve como README.md e abra num preview com listas de tarefas GFM. Confira o estado dos quatro itens e a fonte que os representa.","expected":"Em GFM, dois itens marcados e dois pendentes. O arquivo apenas registra a revisão; não abre links nem publica o guia.","quiz":{"question":"Marcar [x] em conferir saldo faz o sistema efetuar essa conferência?","options":["Não; a marcação registra uma afirmação no documento.","Sim, desde que o arquivo se chame README.md.","Sim, qualquer parser GFM acessa o banco.","Não, porque listas de tarefas não aparecem em nenhum preview."],"answer":0,"explanation":"Uma lista de tarefas é conteúdo; seu uso como evidência exige um processo de revisão e informações verificáveis."},"exercises":[{"id":1,"title":"Tarefa atômica","prompt":"Divida revisar tudo em três itens com critérios claros.","hint":"Separe conteúdo, links e apresentação.","solution":"Crie itens para conferir números do exemplo, abrir links locais e revisar o preview no destino escolhido.","criteria":["Cada item descreve uma tarefa verificável.","Nenhum item depende de uma expressão vaga como tudo."]},{"id":2,"title":"Evidência da revisão","prompt":"Acrescente uma frase que registre como os links foram conferidos.","hint":"Diga escopo e contexto do teste.","solution":"Registre que os links dos arquivos README.md e GUIA.md foram abertos no visualizador escolhido, com data e pendências encontradas.","criteria":["O escopo da conferência é claro.","A data ou versão da revisão é registrada."]},{"id":3,"title":"Estado desatualizado","prompt":"O destino de um link foi renomeado depois de a tarefa ser marcada. O que revisar?","hint":"A afirmação pode perder validade após mudanças.","solution":"Reabra a tarefa de links, atualize o caminho e registre nova conferência. A marca anterior não comprova o conteúdo modificado.","criteria":["Reconhece o efeito da mudança.","Atualiza tarefa e destino de forma coerente."]}],"source":"https://github.github.com/gfm/","caution":"","local":true,"hours":2,"minutes":45},{"id":18,"level":6,"title":"Autolinks, texto riscado e declaração de dialeto","goal":"Distinguir recursos básicos de extensões e escrever alternativas claras.","theory":[{"title":"Autolink básico e estendido","text":"CommonMark reconhece determinadas URLs entre sinais < e > como autolinks. GFM também acrescenta formas de reconhecimento de endereços sem esses delimitadores. Um endereço que virou link num ambiente pode continuar texto em outro."},{"title":"Riscado registra uma alteração","text":"GFM permite texto riscado com tils em pares na forma usada nesta aula. Use isso para mostrar uma revisão curta, sem deixar uma instrução antiga como única fonte da regra. Uma decisão atual precisa estar explícita fora do trecho retirado."},{"title":"Documente o contrato do destino","text":"Quando você usa recursos extras, anote quais são necessários e como o leitor receberá o conteúdo sem eles. Para links importantes, a forma inline com rótulo descritivo costuma ser uma alternativa mais previsível do que depender de detecção automática."}],"code":"# Atualização do procedimento\n\nDialeto principal: GFM.\n\n~~Confirmar antes de conferir as evidências.~~\n\nRegra atual: confira as evidências e só depois registre a decisão.\n\nConsulta com autolink explícito: <https://spec.commonmark.org/0.31.2/>.\n\nConsulta com URL direta no GFM: https://github.github.com/gfm/\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Compare num preview GFM e num modo CommonMark sem extensões, registrando texto riscado e URLs reconhecidas.","expected":"Em GFM, a instrução antiga fica riscada e as duas URLs são links. Em CommonMark básico, o autolink explícito é reconhecido; extensões podem permanecer texto.","quiz":{"question":"Qual afirmação sobre um endereço sem < > está correta?","options":["Ele é obrigatoriamente um link em toda implementação CommonMark.","Seu reconhecimento automático como link pode depender de extensões do renderizador.","Ele executa uma requisição ao ser escrito na fonte.","Ele substitui a necessidade de conferir o destino."],"answer":1,"explanation":"GFM amplia formas de autolink; não generalize o comportamento do seu preview para qualquer ambiente."},"exercises":[{"id":1,"title":"Alternativa portátil","prompt":"Troque a URL direta GFM por um link inline com rótulo descritivo.","hint":"Não dependa de reconhecimento automático do texto.","solution":"Use [Consultar as extensões GFM](https://github.github.com/gfm/).","criteria":["O texto descreve o destino.","A sintaxe funciona como link inline na base CommonMark."]},{"id":2,"title":"Regra vigente","prompt":"Reescreva uma frase riscada sem deixar dúvida sobre qual procedimento vale.","hint":"A alteração visual não basta.","solution":"Mantenha a regra anterior apenas como histórico e escreva Regra atual: conferir antes de confirmar, com data ou versão se necessário.","criteria":["A regra atual está explícita.","O histórico não contradiz o procedimento ativo."]},{"id":3,"title":"Matriz de dialetos","prompt":"Liste quais recursos desta aula dependem de GFM e qual tem forma CommonMark.","hint":"Separe texto riscado, URL direta e autolink explícito.","solution":"Texto riscado e detecção estendida de URL dependem de extensão; a forma <https://...> é autolink básico reconhecido pela especificação.","criteria":["Classifica os três recursos.","Não afirma que todo Markdown possui o mesmo contrato."]}],"source":"https://github.github.com/gfm/","caution":"","local":true,"hours":2,"minutes":45},{"id":19,"level":7,"title":"HTML inline e blocos explícitos","goal":"Reconhecer quando a fonte contém HTML e qual parte cabe ao renderizador.","theory":[{"title":"HTML pode aparecer na fonte","text":"CommonMark reconhece formas de HTML inline e em blocos. Isso permite descrever um elemento quando Markdown não possui uma forma equivalente. A presença na fonte, porém, não obriga todo destino a aceitar a tag ou todos os seus atributos."},{"title":"Bloco e conteúdo inline diferem","text":"O contexto influencia como o parser trata o conteúdo. Não suponha que colocar **texto** dentro de qualquer bloco HTML manterá análise de Markdown da mesma maneira. Separe exemplos pequenos, confira o HTML produzido e a apresentação do destino."},{"title":"Prefira a forma simples quando basta","text":"Um título deve continuar sendo um título Markdown quando a finalidade é só criar a seção. HTML extra aumenta a dependência do ambiente e pode ser removido por sanitização. Use-o por uma necessidade concreta, como marcar uma tecla num renderizador que suporte esse recurso."}],"code":"# Teclas de conferência\n\nPara avançar no exemplo, pressione <kbd>Enter</kbd>.\n\n<p>Este bloco usa <strong>HTML</strong> explícito.</p>\n\nO parágrafo seguinte usa **Markdown** novamente.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Num destino que permita essas tags, Enter aparece como uma tecla, HTML em forte dentro de um parágrafo HTML e o último destaque é produzido pela sintaxe Markdown.","quiz":{"question":"Reconhecer HTML na sintaxe garante que o destino preservará todas as tags e atributos?","options":["Sim, qualquer arquivo .md pode executar qualquer recurso de uma página.","Sim, o nome da tag desativa as regras do site.","Não; o ambiente pode aplicar restrições e sanitização adicionais.","Não, porque CommonMark não reconhece nenhum HTML."],"answer":2,"explanation":"Reconhecimento sintático, política de publicação e apresentação são responsabilidades distintas."},"exercises":[{"id":1,"title":"Forma equivalente","prompt":"Troque o parágrafo HTML por uma forma Markdown equivalente para o destaque.","hint":"Não há necessidade de HTML para apenas criar forte.","solution":"Use Este bloco usa **HTML** como um parágrafo normal. Compare a simplicidade da fonte e o resultado.","criteria":["O significado é preservado.","A forma mais simples é justificada."]},{"id":2,"title":"Suporte de tecla","prompt":"Confira se kbd é preservado pelo seu visualizador e registre o resultado.","hint":"Não generalize a partir de um único preview.","solution":"Se for preservado, registre o ambiente; se for removido ou simplificado, mantenha a instrução compreensível como texto.","criteria":["O resultado foi observado.","O procedimento não depende do estilo da tecla."]},{"id":3,"title":"Markdown no bloco","prompt":"Teste um parágrafo HTML contendo os caracteres **saldo** e compare com o parágrafo Markdown fora dele.","hint":"O contexto de HTML em bloco muda o processamento.","solution":"Observe se os asteriscos permanecem literais no bloco HTML do seu preview. Para portabilidade, evite misturar regras sem conferir.","criteria":["Compara os dois contextos.","Não afirma comportamento universal de extensões."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":20,"level":7,"title":"Seções recolhíveis com details e summary","goal":"Organizar conteúdo suplementar sem esconder ações essenciais.","theory":[{"title":"Um recurso do ambiente","text":"O elemento details com summary pode oferecer uma seção recolhível em destinos que permitam esse HTML, incluindo o comportamento documentado pelo GitHub. Isso é diferente de uma construção específica de CommonMark para expandir conteúdo."},{"title":"O rótulo orienta a escolha","text":"O summary deve explicar o que será revelado. Um rótulo como detalhes adicionais é menos útil que exemplo numérico de saldo. Mantenha linhas vazias e confira como o ambiente processa Markdown dentro do elemento, pois esse comportamento pode variar."},{"title":"Essencial continua visível","text":"Pré-requisitos, efeitos e regras para confirmar uma OS não deveriam depender de abrir uma área opcional. Use a parte recolhível para explicações complementares. Inclua uma alternativa simples se o conjunto precisar funcionar num destino sem suporte."}],"code":"# Conferir o saldo\n\nAntes de confirmar, confira se o saldo atende à quantidade da OS.\n\n<details>\n<summary>Exemplo numérico de uma baixa de estoque</summary>\n\nO saldo inicial é **3**. Uma OS solicita **2** unidades; após uma confirmação válida, resta **1**.\n\n</details>\n\nRegistre uma pendência se a quantidade solicitada exceder o saldo.\n","filename":"README.md","language":"markdown","run":"Salve como README.md e abra num preview que documente suporte a details/summary. Abra e feche a seção; depois leia a fonte como alternativa sem interação.","expected":"Num preview GitHub compatível, a regra principal aparece fora da área recolhível e o resumo abre uma explicação numérica. Um destino sem suporte pode apresentar o conteúdo sem a mesma interação.","quiz":{"question":"Que conteúdo é mais adequado dentro de uma seção recolhível opcional?","options":["O único aviso de um efeito irreversível.","Todos os pré-requisitos indispensáveis, sem resumo.","A única descrição da ação principal do documento.","Uma explicação complementar, com a regra essencial já visível no texto principal."],"answer":3,"explanation":"Conteúdo indispensável à tarefa deve permanecer encontrável sem depender de uma interação opcional."},"exercises":[{"id":1,"title":"Resumo específico","prompt":"Substitua um summary chamado Mais por um rótulo que descreva seu conteúdo.","hint":"Nomeie a explicação oferecida.","solution":"Use Exemplo numérico de uma baixa de estoque para que o leitor saiba por que abrir a seção.","criteria":["O rótulo descreve o conteúdo.","Não depende de adivinhar a finalidade da área."]},{"id":2,"title":"Alternativa sem HTML","prompt":"Reescreva o mesmo exemplo usando apenas um título e um parágrafo.","hint":"A interação não deve ser necessária para compreender os números.","solution":"Use ### Exemplo numérico seguido da explicação do saldo. O conteúdo permanece disponível sem details.","criteria":["A alternativa preserva a informação.","Usa apenas estruturas básicas."]},{"id":3,"title":"Regra escondida","prompt":"Mova a regra de pendência para dentro da área recolhível e explique por que essa versão é pior.","hint":"A regra altera a decisão do leitor.","solution":"Ela fica mais difícil de encontrar e pode ser ignorada como material opcional. Restaure a regra no texto principal.","criteria":["Identifica o risco de descoberta da regra.","Restaura a posição coerente com sua importância."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/organizing-information-with-collapsed-sections","caution":"","local":true,"hours":2,"minutes":45},{"id":21,"level":7,"title":"Sanitização e contrato de publicação","goal":"Distinguir conteúdo reconhecido, conteúdo permitido e recursos realmente disponíveis.","theory":[{"title":"Parser não é toda a publicação","text":"Um parser transforma a sintaxe em uma representação. O serviço pode depois filtrar HTML, ajustar links e acrescentar recursos. A especificação GFM documenta que o GitHub aplica processamento e sanitização além da conversão da sintaxe."},{"title":"Conteúdo externo tem dependências","text":"Imagens externas e links precisam de endereços e disponibilidade próprios. Não coloque segredos em URLs de exemplo nem trate uma imagem remota como prova de um estado atual. Para documentação compartilhada, use dados fictícios e recursos cujo uso tenha sido decidido."},{"title":"Uma política explícita ajuda o autor","text":"Declare o conjunto necessário de recursos e mantenha a regra principal em estruturas básicas. Se um destino bloqueia um recurso, adapte o documento ao contrato desse destino. Não tente transformar um arquivo de orientação numa maneira de contornar os controles do ambiente."}],"code":"# Contrato deste guia\n\n## Conteúdo necessário\n\n- Títulos, parágrafos e listas.\n- Links descritivos para as fontes.\n- Blocos de código exibidos como texto.\n\n## Conteúdo opcional\n\nA seção recolhível pode ser substituída por um título normal se o destino não aceitar o elemento.\n\n## Recursos externos\n\nA [especificação GFM](https://github.github.com/gfm/) é uma referência externa, não uma dependência para executar o procedimento da oficina.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um contrato legível com recursos necessários e opcionais. O arquivo não contém conteúdo executável nem exige um elemento HTML para entender a regra.","quiz":{"question":"Por que um HTML pode aparecer num preview local e ser removido no destino?","options":["O destino pode aplicar uma política de sanitização diferente depois de analisar a sintaxe.","A extensão .md muda sozinha para um formato secreto.","Todo HTML local é automaticamente certificado como seguro.","Um link por referência desativa a sanitização."],"answer":0,"explanation":"A política do ambiente é uma camada adicional ao reconhecimento da sintaxe."},"exercises":[{"id":1,"title":"Inventário de recursos","prompt":"Liste os recursos usados por um documento seu e marque quais são indispensáveis.","hint":"Separe conteúdo básico de interação opcional.","solution":"Registre por exemplo títulos e listas como necessários, details e diagramas como opcionais, conforme a função real.","criteria":["O inventário corresponde ao arquivo.","A importância é justificada pela tarefa do leitor."]},{"id":2,"title":"Destino restrito","prompt":"Prepare uma versão sem HTML de um guia que usa kbd e details.","hint":"Use texto e títulos para as mesmas informações.","solution":"Mencione Enter como literal e transforme a área recolhível em subseção, preservando as instruções.","criteria":["Não perde informação essencial.","A versão evita dependência de HTML."]},{"id":3,"title":"Link de exemplo","prompt":"Revise uma URL que contém um token fictício parecido com segredo e proponha um exemplo melhor.","hint":"Nem o formato de um segredo precisa ser necessário para explicar o destino.","solution":"Use um endereço público de demonstração e descreva campos sensíveis em texto, sem publicar valores reais ou URLs autenticadas.","criteria":["O exemplo não contém credenciais reais.","A finalidade do link continua clara."]}],"source":"https://github.github.com/gfm/","caution":"","local":true,"hours":2,"minutes":45},{"id":22,"level":8,"title":"README que orienta o primeiro contato","goal":"Apresentar objetivo, público, entrada e limitações sem transformar o README num manual inteiro.","theory":[{"title":"A primeira pergunta é para que serve","text":"Um README costuma ser o ponto de entrada de um conjunto de arquivos. Diga o que é o projeto e quem deve usá-lo antes de uma longa lista de detalhes. O leitor precisa decidir se encontrou o material certo e qual passo seguir."},{"title":"Um caminho inicial curto","text":"Separe pré-requisitos, um primeiro percurso e links para aprofundamento. Se o projeto é documental, não invente comandos de instalação de uma aplicação inexistente. Se há um programa, os comandos precisam ser executáveis no contexto e versão declarados."},{"title":"Limites ajudam a escolha","text":"Uma limitação relevante muda o que o leitor pode esperar. Diga que os dados são fictícios e que um conjunto de exemplos não é o sistema de produção. Deixe referência detalhada e solução de problemas em arquivos próprios quando crescerem."}],"code":"# Oficina documental\n\nConjunto de exemplos de documentação para estudar ordens de serviço e estoque. Público: aluno e revisor do curso.\n\n## Começar\n\n1. Leia o cenário fictício OS-1 abaixo.\n2. Compare a quantidade solicitada com o saldo.\n3. Registre se a conferência pode continuar.\n\n## Cenário OS-1\n\n- Saldo do item A: 3.\n- Quantidade solicitada: 2.\n- Evidência: disponível para conferência no cenário.\n\n## Limites\n\nEste repositório documental não executa a confirmação da OS. As decisões e os dados são exemplos de estudo.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um README com objetivo, público, percurso inicial, cenário e limite. O leitor pode realizar o raciocínio descrito sem instalar uma aplicação.","quiz":{"question":"Qual informação deve aparecer cedo num README de entrada?","options":["Todas as decisões históricas antes de explicar o projeto.","O objetivo do projeto, seu público e um caminho inicial claro.","Apenas um logotipo sem texto.","Uma lista de comandos que o projeto não possui."],"answer":1,"explanation":"A apresentação precisa orientar a escolha e o primeiro passo; detalhes podem ser ligados por documentos próprios."},"exercises":[{"id":1,"title":"Público específico","prompt":"Adapte o README para um operador que quer conferir uma OS, não para um desenvolvedor.","hint":"Use tarefas e termos do trabalho desse leitor.","solution":"Explique onde encontrar a OS, quais dados conferir e quando registrar pendência; deixe detalhes de implementação fora do percurso inicial.","criteria":["O público está identificado.","O primeiro passo responde a uma tarefa desse público."]},{"id":2,"title":"Link para crescer","prompt":"Proponha uma seção que deveria sair do README quando se tornar longa.","hint":"Pense em referência detalhada ou diagnóstico.","solution":"Uma lista de todos os erros pode virar GUIA-ERROS.md com um link descritivo no README; crie e confira o arquivo antes de publicar o destino.","criteria":["A divisão tem propósito claro.","Não cria um link apresentado como funcional sem o arquivo."]},{"id":3,"title":"Limite verificável","prompt":"Escreva uma limitação que altere a expectativa do leitor sem ser uma frase vaga.","hint":"Diga qual capacidade está ausente.","solution":"Use Os exemplos não gravam alterações num banco; eles servem apenas para praticar a conferência documental.","criteria":["A ausência é concreta.","Não contradiz o que o material oferece."]}],"source":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes","caution":"","local":true,"hours":2,"minutes":45},{"id":23,"level":8,"title":"Tutorial orientado a uma tarefa","goal":"Escrever uma sequência com ponto de partida, ações e resultado observável.","theory":[{"title":"Tutorial tem um percurso","text":"Escolha uma tarefa pequena e um cenário controlado. Diga o que o leitor tem antes de começar e o que deve conseguir ao final. Não tente ensinar todos os conceitos e todas as exceções no mesmo percurso de entrada."},{"title":"Cada ação possui resultado","text":"Um passo deve ter uma ação concreta e, quando útil, o resultado que mostra que o leitor pode continuar. Não pule um pré-requisito por parecer óbvio ao autor. Use dados consistentes entre os passos e a saída final."},{"title":"Distingua tutorial de referência","text":"A referência descreve opções e contratos para consulta; o tutorial guia uma execução específica. Eles podem se ligar, mas não precisam repetir tudo. Um leitor deve saber se está seguindo um caminho ou consultando todas as possibilidades."}],"code":"# Conferir a OS-1\n\n## Antes de começar\n\nUse o cenário fictício: saldo 3, solicitação de 2 unidades e evidência disponível para revisão. Este tutorial é documental.\n\n## Passos\n\n1. Identifique a OS como `OS-1`. Resultado: você sabe qual registro está analisando.\n2. Compare 2 com o saldo 3. Resultado: a quantidade cabe no saldo.\n3. Registre que a evidência ainda precisa ser conferida. Resultado: a presença do arquivo não foi confundida com aprovação.\n\n## Resultado esperado\n\nA análise numérica permite continuar a conferência. A decisão final depende da revisão da evidência; nenhuma baixa foi executada por este texto.\n","filename":"GUIA.md","language":"markdown","run":"Salve como GUIA.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um tutorial documental com pré-requisitos, três passos e resultado que distingue análise numérica de confirmação final.","quiz":{"question":"O que diferencia principalmente este tutorial de uma referência de campos?","options":["Ele precisa listar todas as APIs existentes.","Ele deve ocultar os dados do cenário.","Ele guia uma tarefa específica com ponto de partida e resultado.","Ele transforma qualquer exemplo numa ação automática."],"answer":2,"explanation":"Um tutorial oferece um caminho controlado; a referência serve para consultar o contrato de cada elemento."},"exercises":[{"id":1,"title":"Cenário de rejeição","prompt":"Adapte o tutorial para saldo 1 e solicitação de 2 unidades.","hint":"Revise também o resultado final, não apenas os números iniciais.","solution":"No passo de comparação, identifique insuficiência; o resultado passa a registrar pendência e impedir continuidade para confirmação.","criteria":["Os números são coerentes em todo o documento.","O resultado corresponde à condição insuficiente."]},{"id":2,"title":"Pré-requisito omitido","prompt":"Acrescente um pré-requisito necessário para conferir uma evidência visual.","hint":"Pense no que o leitor precisa conseguir observar.","solution":"Informe que a evidência deve estar disponível e legível para a conferência; se faltar ou não puder ser lida, registre a pendência.","criteria":["O pré-requisito é acionável.","Há uma resposta clara ao seu não atendimento."]},{"id":3,"title":"Resultado por passo","prompt":"Reescreva faça o necessário como uma ação e um resultado verificáveis.","hint":"Use objeto, comparação e condição.","solution":"Use Compare o ID exibido com OS-1; continue apenas se os dois coincidirem.","criteria":["A ação pode ser executada pelo leitor.","O critério de continuidade está explícito."]}],"source":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes","caution":"","local":true,"hours":2,"minutes":45},{"id":24,"level":8,"title":"Referência de campos, estados e vocabulário","goal":"Criar um documento de consulta com contratos e exemplos consistentes.","theory":[{"title":"Consulta precisa de precisão","text":"Uma referência responde o que significa um campo, quais valores aceita e como ele participa de uma regra. Ela não precisa repetir uma longa introdução a cada consulta. Títulos previsíveis e exemplos curtos facilitam localizar um elemento."},{"title":"Ausência não é um valor qualquer","text":"Defina como representar dado ausente e diferencie isso de zero ou string vazia quando o domínio exige. Evite termos vagos como normal e correto sem explicar a condição. A documentação não impõe validação ao programa; ela descreve o contrato que ele deve cumprir."},{"title":"Vocabulário consistente","text":"Se conferida e confirmada significam etapas diferentes, preserve os nomes em todo o conjunto. Um glossário pequeno pode evitar que duas palavras parecidas virem estados intercambiáveis. Confira os exemplos de tutorial contra essa referência."}],"code":"# Referência de uma OS de estudo\n\n## Campo id\n\nIdentificador textual da ordem. Exemplo: `OS-1`. Este exemplo usa o formato OS seguido de hífen e um número positivo.\n\n## Campo quantidade\n\nNúmero inteiro de unidades solicitadas. Valor mínimo neste cenário: 1. Zero não representa uma solicitação válida.\n\n## Estados\n\n- `aberta`: conferência ainda não concluída.\n- `conferida`: informações avaliadas; confirmação ainda não registrada.\n- `confirmada`: confirmação registrada no cenário descrito.\n\n## Vocabulário\n\nConferir significa avaliar os dados. Confirmar significa registrar a decisão permitida pelo procedimento.\n","filename":"REFERENCIA.md","language":"markdown","run":"Salve como REFERENCIA.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um documento de consulta com dois campos, três estados e distinção explícita entre conferir e confirmar.","quiz":{"question":"Uma referência diz quantidade é normal. Qual informação falta?","options":["Uma fonte maior em todas as linhas.","Um avatar para cada campo.","O número da linha do título no editor.","O tipo, os limites e o significado esperado do valor."],"answer":3,"explanation":"O contrato precisa tornar os valores compreensíveis e verificáveis; um adjetivo vago não define validação."},"exercises":[{"id":1,"title":"Contrato de saldo","prompt":"Documente saldo como inteiro não negativo, incluindo o significado de zero.","hint":"Defina a regra que será conferida.","solution":"Use saldo como número de unidades disponíveis, mínimo 0; zero significa ausência de unidades disponíveis, não campo ausente.","criteria":["Tipo e limite estão explícitos.","Distingue zero de ausência."]},{"id":2,"title":"Nomes coerentes","prompt":"Revise um tutorial que usa concluída como sinônimo de conferida sem definir esse estado.","hint":"Compare os termos com a referência.","solution":"Use o estado definido ou acrescente uma definição deliberada com efeito no fluxo. Não misture termos apenas por estilo.","criteria":["A terminologia fica consistente.","Uma mudança de estado possui significado definido."]},{"id":3,"title":"Exemplo inválido","prompt":"Escreva um contraexemplo de quantidade e explique por que ele é rejeitado no contrato.","hint":"Use os limites da própria referência.","solution":"Quantidade 0 ou 1.5 é inválida neste cenário, pois a regra exige inteiro mínimo 1.","criteria":["O contraexemplo viola uma regra documentada.","A explicação aponta essa regra."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":25,"level":9,"title":"Índices e navegação entre arquivos","goal":"Projetar um conjunto documental em que cada público encontre seu percurso.","theory":[{"title":"A divisão segue uma necessidade","text":"Separar arquivos deve ajudar a tarefa ou a manutenção. Um manual do operador, uma referência de campos e um histórico têm públicos e usos distintos. Evite quebrar cada parágrafo num arquivo que obriga o leitor a navegar sem ganhar clareza."},{"title":"Índice descreve percursos","text":"Um bom índice não é só uma lista alfabética de nomes. Diga quem deve começar por cada recurso e em qual situação consultá-lo. Links descritivos tornam a divisão visível sem exigir conhecimento da organização interna das pastas."},{"title":"Confira origem e retorno","text":"A partir do README na raiz, docs/GUIA.md aponta para uma subpasta. Dentro desse guia, ../README.md pode ser o retorno. Esses caminhos descrevem a estrutura proposta; os arquivos devem ser criados e conferidos antes de declarar o conjunto entregue."}],"code":"# Manual da oficina\n\n## Começar por público\n\n- Operador: [seguir a conferência](docs/GUIA.md).\n- Revisor técnico: [consultar campos e estados](docs/REFERENCIA.md).\n- Responsável pelo material: [revisar as mudanças](docs/HISTORICO.md).\n\n## Estrutura proposta\n\n- `README.md`: entrada deste conjunto.\n- `docs/GUIA.md`: procedimento do operador.\n- `docs/REFERENCIA.md`: contratos dos dados.\n- `docs/HISTORICO.md`: alterações publicadas.\n","filename":"README.md","language":"markdown","run":"Salve como README.md na raiz de uma pasta de laboratório. Crie docs/GUIA.md, docs/REFERENCIA.md e docs/HISTORICO.md antes de testar a navegação local.","expected":"Um índice com três percursos e a estrutura necessária. Os links locais dependem da criação dos arquivos em docs.","quiz":{"question":"Um link de retorno dentro de docs/GUIA.md para o README da pasta pai normalmente usa qual caminho relativo?","options":["../README.md","docs/docs/README.md","GUIA.md/README.md","https://README.md obrigatoriamente"],"answer":0,"explanation":"O caminho sobe um diretório a partir do documento de origem. A resolução real ainda deve ser conferida no destino de publicação."},"exercises":[{"id":1,"title":"Monte o conjunto","prompt":"Crie os três documentos mínimos em docs e teste cada link do índice.","hint":"Conteúdo de placeholder sem orientação não conclui a entrega.","solution":"Dê a cada arquivo título, finalidade e conteúdo pertinente; depois navegue a partir do README.","criteria":["Os três arquivos existem.","Cada destino corresponde à descrição do índice."]},{"id":2,"title":"Voltar ao início","prompt":"Acrescente um link de retorno ao README em GUIA.md.","hint":"O contexto do caminho é o próprio guia.","solution":"Use [Voltar ao início](../README.md) dentro de docs/GUIA.md e abra o destino no preview que permita navegação local.","criteria":["O caminho parte de docs.","O link foi conferido no contexto do guia."]},{"id":3,"title":"Percurso por tarefa","prompt":"Crie um item de índice para quem procura solucionar uma pendência de evidência.","hint":"O rótulo deve descrever a tarefa, não só o nome de arquivo.","solution":"Use Consultar pendências de evidência apontando para a seção ou arquivo realmente criado para esse assunto.","criteria":["O rótulo comunica a tarefa.","O destino foi criado e conferido."]}],"source":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes","caution":"","local":true,"hours":2,"minutes":45},{"id":26,"level":9,"title":"Âncoras estáveis e revisão de links","goal":"Entender como mudanças de títulos e arquivos afetam a navegação existente.","theory":[{"title":"Link é uma dependência","text":"Quando um documento cita uma seção de outro, o título e o identificador gerado passam a fazer parte da navegação. Renomear uma seção pode ser correto e ainda assim quebrar usos antigos. Procure quem depende do destino antes de publicar a mudança."},{"title":"Repetições exigem atenção","text":"Renderizadores podem resolver títulos repetidos acrescentando diferenças nos IDs. Não dependa de um fragmento deduzido de memória, especialmente com acentos ou pontuação. Use a forma observada no destino e títulos distintos quando a diferença de assunto permitir."},{"title":"Rótulo e conteúdo também envelhecem","text":"Um link que abre não está necessariamente correto. O destino pode ter mudado de propósito ou deixado de representar a versão descrita. A revisão precisa conferir existência, seção alcançada e coerência entre o rótulo e o que o leitor encontra."}],"code":"# Etapas de conferência\n\n- [Conferência inicial](#conferencia-inicial).\n- [Conferência final](#conferencia-final).\n\n## Conferencia inicial\n\nIdentifique o registro e os dados necessários.\n\n## Conferencia final\n\nCompare a decisão com as evidências e registre a conclusão.\n\nOs fragmentos acima seguem a geração usual do GitHub. Confirme os IDs no renderizador de destino.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Num preview GitHub compatível, cada link alcança uma seção distinta. O texto declara a política usada em vez de prometer IDs universais.","quiz":{"question":"Depois de renomear uma seção, qual revisão é necessária?","options":["Só mudar a cor do título.","Conferir o ID gerado e os links que dependiam da seção, incluindo o sentido dos rótulos.","Presumir que todo fragmento antigo continua funcionando.","Renomear qualquer outro arquivo aleatoriamente."],"answer":1,"explanation":"A navegação depende de destinos e identificadores; uma mudança também pode exigir ajustar a descrição do link."},"exercises":[{"id":1,"title":"Renomeie com revisão","prompt":"Troque Conferencia final por Decisao registrada e atualize a navegação.","hint":"Confira o ID gerado de verdade.","solution":"No destino que gere decisao-registrada, atualize o fragmento e o rótulo; registre se o seu visualizador usar outra política.","criteria":["O link alcança a nova seção.","O rótulo descreve o conteúdo atual."]},{"id":2,"title":"Títulos repetidos","prompt":"Crie duas seções Teste no laboratório e inspecione os fragmentos gerados.","hint":"Não assuma que ambos terão o mesmo destino.","solution":"Observe os identificadores produzidos e depois dê nomes descritivos distintos, se os assuntos forem diferentes.","criteria":["Registra a política observada.","Propõe títulos que reduzam ambiguidade."]},{"id":3,"title":"Link abre, mas erra","prompt":"Um link chamado Campos obrigatórios abre uma seção de histórico. Explique a falha e corrija.","hint":"Abrir uma URL não basta.","solution":"Corrija o destino para a referência apropriada ou altere o rótulo se o histórico era o conteúdo pretendido.","criteria":["Reconhece o erro de significado.","A correção alinha rótulo e destino."]}],"source":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes","caution":"","local":true,"hours":2,"minutes":45},{"id":27,"level":9,"title":"Modelos e convenções de autoria","goal":"Criar modelos que orientem informações necessárias sem transformar placeholders em fatos.","theory":[{"title":"Modelo ensina o que preencher","text":"Um bom modelo define as partes esperadas e explica o tipo de informação de cada uma. Um marcador como PREENCHER precisa ser visível e removido ou justificado antes da entrega. Não use valores de exemplo com aparência de registros reais sem contexto."},{"title":"Convenções reduzem variação inútil","text":"Decida nomes de arquivos, estrutura de títulos e representação dos estados. Essas escolhas editoriais não são regras do parser Markdown. A finalidade é manter um conjunto fácil de percorrer e revisar por mais de uma pessoa."},{"title":"Evite duplicar a fonte da regra","text":"Um modelo pode apontar para a referência principal em vez de repetir um contrato inteiro. Cópias de uma mesma regra envelhecem de formas diferentes. Se uma mudança afeta o modelo, revise os documentos derivados que precisam se adaptar."}],"code":"# Modelo de relatório de OS\n\nEste arquivo é um modelo. Substitua os marcadores antes de entregar um relatório.\n\n## Identificação\n\nOS: `PREENCHER_ID`. Revisão: `PREENCHER_DATA`.\n\n## Observações\n\n- PREENCHER_FATO_OBSERVADO.\n\n## Limites da conferência\n\nPREENCHER_O_QUE_NAO_FOI_VERIFICADO.\n\n## Decisão e próximo passo\n\nPREENCHER_DECISAO_E_JUSTIFICATIVA.\n","filename":"MODELO.md","language":"markdown","run":"Salve como MODELO.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um modelo explicitamente incompleto, com campos que orientam o preenchimento. Ele não deve ser apresentado como relatório final sem substituir os marcadores.","quiz":{"question":"Qual prática evita que um modelo seja confundido com um relatório concluído?","options":["Copiar datas e IDs de produção sem contexto.","Remover a palavra modelo e manter todos os campos genéricos.","Identificar o arquivo como modelo e usar marcadores de preenchimento claros.","Marcar tudo como verificado para preencher mais rápido."],"answer":2,"explanation":"O modelo precisa distinguir orientação de autoria de afirmações sobre um fato ocorrido."},"exercises":[{"id":1,"title":"Preencha um cenário","prompt":"Crie uma cópia do modelo com os dados fictícios OS-1, saldo 3 e solicitação 2.","hint":"Remova os marcadores e preserve limites reais do cenário.","solution":"Registre os números e que a autenticidade da evidência ainda não foi conferida; a decisão não pode afirmar uma validação inexistente.","criteria":["Não restam placeholders acidentais.","O relatório distingue fatos e limites."]},{"id":2,"title":"Convenção curta","prompt":"Escreva três convenções editoriais para os documentos do projeto.","hint":"Escolha regras que um revisor consiga verificar.","solution":"Use nomes de arquivos consistentes, um título principal descritivo e estados escritos conforme a referência. Identifique como convenção do projeto.","criteria":["As três regras são verificáveis.","Não são apresentadas como exigências universais de Markdown."]},{"id":3,"title":"Fonte principal","prompt":"Explique onde manter a definição de status quando vários modelos a usam.","hint":"Evite múltiplas cópias independentes.","solution":"Mantenha a definição na referência de campos e ligue os modelos a ela. Ao alterar o contrato, revise os usos e exemplos afetados.","criteria":["Escolhe uma fonte principal.","Inclui revisão dos documentos dependentes."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":28,"level":10,"title":"Mermaid como extensão com alternativa textual","goal":"Acrescentar um diagrama quando o destino oferece suporte sem tornar a regra dependente dele.","theory":[{"title":"A cerca sozinha não cria o diagrama","text":"Em CommonMark, uma cerca com o identificador mermaid continua sendo um bloco de código. Alguns ambientes, como os espaços documentados pelo GitHub, usam esse identificador para acionar um renderizador de diagramas. O suporte e a versão da ferramenta são parte do destino."},{"title":"Mostre a relação necessária","text":"Um fluxo ajuda quando há estados, condições ou caminhos alternativos relevantes. Mantenha os rótulos curtos e o diagrama focado numa relação. Não tente desenhar o manual inteiro em uma figura que exige percorrer muitas setas."},{"title":"Equivalência em texto","text":"A regra principal precisa estar escrita em linguagem clara fora do diagrama. Esse texto ajuda leitores que não recebem a visualização ou usam outras formas de acesso. Verifique se um caminho foi atualizado nos dois lugares quando o procedimento mudar."}],"code":"# Decisão de confirmação\n\n## Regra em texto\n\nA OS começa aberta. Quando evidências e saldo foram conferidos e atendem à regra, a decisão pode seguir para confirmação. Se falta alguma condição, registre uma pendência.\n\n## Diagrama opcional\n\n```mermaid\nflowchart TD\n  A[\"OS aberta\"] --> B{\"Condições atendidas?\"}\n  B -->|Sim| C[\"Confirmar\"]\n  B -->|Não| D[\"Registrar pendência\"]\n```\n\nO diagrama exige um destino com suporte a Mermaid. A regra em texto é a referência quando a extensão não estiver disponível.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Confira primeiro o texto e as cercas no preview. Para ver o diagrama, use um destino que documente suporte a Mermaid; num preview comum ele pode permanecer código.","expected":"Num destino com Mermaid compatível, um fluxo com condição e dois caminhos. Num preview comum, a sintaxe pode aparecer como código; a regra continua explicada em texto.","quiz":{"question":"O que CommonMark básico faz com uma cerca identificada como mermaid?","options":["Executa obrigatoriamente qualquer versão de Mermaid.","Converte o fluxo em uma transação de estoque.","Remove todos os parágrafos anteriores.","Trata o conteúdo como bloco de código; o diagrama depende de suporte extra."],"answer":3,"explanation":"A cerca informa conteúdo literal e pode oferecer um identificador; a integração com um renderizador de diagramas é uma extensão."},"exercises":[{"id":1,"title":"Ramo adicional","prompt":"Se uma conferência tiver uma decisão de solicitar evidência, escreva primeiro a regra em texto e depois proponha o diagrama.","hint":"A figura deve corresponder aos caminhos descritos.","solution":"Descreva o estado que exige evidência e ligue-o ao próximo passo sem contradizer a condição de confirmação; mantenha o diagrama pequeno.","criteria":["Os ramos têm equivalência textual.","O diagrama não acrescenta regra ausente no texto."]},{"id":2,"title":"Destino sem extensão","prompt":"Abra a amostra num preview sem Mermaid e avalie se a tarefa ainda pode ser entendida.","hint":"A sintaxe pode ficar como bloco de código.","solution":"O leitor deve entender a condição e os dois resultados pelo parágrafo. Se não conseguir, melhore a alternativa textual.","criteria":["Registra o comportamento real do preview.","Confirma que a regra não depende da figura."]},{"id":3,"title":"Mudança sincronizada","prompt":"Altere a regra para manter pendente quando a evidência não for legível. Revise texto e rótulos.","hint":"Não basta mudar só uma seta.","solution":"Inclua legibilidade nas condições atendidas e explique a pendência; a condição do diagrama deve representar a mesma decisão.","criteria":["Texto e figura continuam coerentes.","A alteração não torna a confirmação automática pela simples existência do arquivo."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/working-with-advanced-formatting/creating-diagrams","caution":"","local":true,"hours":2,"minutes":45},{"id":29,"level":10,"title":"Front matter e metadados de um gerador","goal":"Separar metadados específicos de uma ferramenta do corpo Markdown portátil.","theory":[{"title":"O gerador define o contrato","text":"Front matter costuma ser um bloco de metadados no começo do arquivo, mas sua sintaxe e efeito dependem da ferramenta. No Jekyll, YAML entre delimitadores no início é processado como metadados. Isso não é uma regra de todos os arquivos Markdown."},{"title":"Metadado não substitui conteúdo","text":"Um title em metadados pode ser usado pelo tema, pelo índice ou por outra etapa configurada. Um preview comum pode apenas mostrar parte dessas linhas como conteúdo. Mantenha título e explicações essenciais no corpo quando precisar de leitura portátil."},{"title":"Campos têm tipos e consumidores","text":"Declare quais campos o projeto usa e quem os interpreta. Uma data entre aspas é uma escolha explícita de texto no exemplo. Criar um campo revisao não faz um sistema revisar o documento automaticamente; ele precisa de um processo que o utilize."}],"code":"---\ntitle: \"Guia de conferência\"\nrevisao: \"2026-10-23\"\n---\n\n# Guia de conferência\n\nEste corpo é a orientação legível do documento. Os metadados acima só têm efeito em um gerador configurado para interpretá-los.\n\n## Regra\n\nConfira os dados antes de registrar a decisão.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Compare o preview comum com a documentação do gerador escolhido. A aula não exige instalar Jekyll; não trate a exibição local como prova de processamento dos metadados.","expected":"Num gerador configurado para esse front matter, os campos ficam disponíveis ao processamento definido. Num preview Markdown comum, o bloco pode aparecer como separador e texto ou outra estrutura; não há garantia de ocultá-lo.","quiz":{"question":"Escrever revisao no front matter faz qualquer preview validar a atualidade do guia?","options":["Não; o campo só produz o efeito que uma ferramenta ou processo definir.","Sim, todo parser consulta a data do servidor.","Sim, YAML executa a conferência por padrão.","Não, porque nenhum gerador aceita metadados."],"answer":0,"explanation":"Metadados não são comportamento automático universal. É necessário conhecer o consumidor do campo."},"exercises":[{"id":1,"title":"Sem metadados","prompt":"Prepare uma versão do guia para um destino que aceita apenas CommonMark.","hint":"Leve a informação essencial para o corpo.","solution":"Remova o bloco específico e inclua Revisão documental: 23/10/2026 como texto abaixo do título, sem alegar revisão de conteúdo não executada.","criteria":["O documento continua compreensível.","Não depende de processamento de front matter."]},{"id":2,"title":"Contrato dos campos","prompt":"Descreva title e revisao numa convenção do projeto.","hint":"Informe significado e consumidor.","solution":"Defina title como rótulo do índice quando o gerador configurado o usa e revisao como texto de referência da última revisão documental registrada.","criteria":["Os dois campos têm significado explícito.","Não atribui efeito automático inexistente."]},{"id":3,"title":"Posição do bloco","prompt":"No cenário Jekyll, coloque um parágrafo antes dos delimitadores e investigue por que o resultado pode mudar.","hint":"O contrato do gerador exige o bloco no começo.","solution":"Restaure os metadados no início do arquivo conforme a documentação da ferramenta; não generalize essa regra a outros geradores.","criteria":["Relaciona o comportamento à ferramenta.","Distingue front matter de um bloco Markdown comum."]}],"source":"https://jekyllrb.com/docs/front-matter/","caution":"","local":true,"hours":2,"minutes":45},{"id":30,"level":10,"title":"Notas, fórmulas e MDX: limites das extensões","goal":"Avaliar recursos extras sem confundir dialetos ou exigir componentes para ler uma regra.","theory":[{"title":"Nem tudo que um site mostra é GFM básico","text":"O GitHub oferece recursos adicionais documentados, como notas de rodapé e alertas, que não devem ser deduzidos apenas da especificação formal GFM. Outros ambientes podem ter fórmulas matemáticas, diretivas e sintaxes diferentes. Confirme o contrato do local específico."},{"title":"MDX é outro formato e pipeline","text":"MDX combina Markdown com recursos como JSX e expressões. Um arquivo .md não ganha essas capacidades automaticamente. Usar componentes exige um ambiente e dependências próprios; para um manual portátil, não faça a leitura da regra principal depender de renderização de componentes."},{"title":"Faça uma escolha deliberada","text":"Uma nota pode guardar uma observação complementar, mas não deve esconder uma condição indispensável. Para um conjunto que precisa funcionar em vários destinos, mantenha explicação em texto e registre quais extensões são opcionais. Não acrescente recursos só porque estão disponíveis."}],"code":"# Quantidade e saldo\n\nA quantidade solicitada deve caber no saldo disponível.[^saldo]\n\n## Explicação visível\n\nNeste exemplo, saldo 3 e solicitação 2 permitem continuar a conferência numérica; saldo 1 e solicitação 2 exigem pendência.\n\n## Compatibilidade\n\nA nota de rodapé usa uma extensão do destino. O texto principal não exige suporte a notas, fórmulas ou MDX.\n\n[^saldo]: A conferência numérica não substitui a revisão das demais condições da OS.\n","filename":"README.md","language":"markdown","run":"Salve como README.md. Confira a leitura básica e, se houver suporte documentado, a nota de rodapé no destino. A aula não exige executar componentes MDX nem instalar um gerador.","expected":"Num destino GitHub que suporte notas, a referência pode levar à nota. Num preview sem essa extensão, a sintaxe pode aparecer como texto ou ser interpretada de outra forma; a explicação essencial continua no corpo.","quiz":{"question":"Qual afirmação sobre MDX está correta?","options":["É apenas outro nome para toda a especificação CommonMark.","Ele exige um formato e um pipeline com suporte próprio; não é uma capacidade automática de qualquer .md.","Funciona integralmente em qualquer preview sem configuração.","É obrigatório para escrever listas e títulos."],"answer":1,"explanation":"Recursos de componentes e expressões pertencem ao contrato MDX, não à base de todos os renderizadores Markdown."},"exercises":[{"id":1,"title":"Nota dispensável","prompt":"Transforme a nota do exemplo em um parágrafo visível para uma edição portátil.","hint":"A informação pode ser expressa sem extensão.","solution":"Remova a referência e a definição e mantenha a observação no corpo, perto da explicação numérica.","criteria":["A versão não depende de notas.","O sentido original permanece."]},{"id":2,"title":"Inventário de extensões","prompt":"Escreva uma lista distinguindo tabelas GFM, Mermaid, front matter e MDX.","hint":"Não agrupe todos como padrão Markdown.","solution":"Indique tabelas como extensão GFM; Mermaid depende de renderizador de diagramas; front matter depende do gerador; MDX tem formato e integração próprios.","criteria":["Classifica os quatro recursos.","Declara os consumidores ou dependências relevantes."]},{"id":3,"title":"Recurso com propósito","prompt":"Uma equipe propõe um componente MDX para exibir uma única frase. Avalie a escolha para um manual que será lido como texto.","hint":"Compare benefício e dependência.","solution":"Uma frase simples pode ficar num parágrafo; o componente só se justifica se oferecer uma capacidade necessária e houver uma alternativa adequada ao destino.","criteria":["Avalia o propósito concreto.","Considera portabilidade e leitura da fonte."]}],"source":"https://docs.github.com/en/get-started/writing-on-github/getting-started-with-writing-and-formatting-on-github/basic-writing-and-formatting-syntax","caution":"","local":true,"hours":2,"minutes":45},{"id":31,"level":11,"title":"Registros de decisão com contexto e consequência","goal":"Documentar uma escolha de projeto de modo que possa ser revisada no futuro.","theory":[{"title":"A escolha precisa de contexto","text":"Um registro de decisão explica qual problema levou à escolha e quais restrições importavam. Apenas afirmar usamos arquivos separados deixa o leitor sem saber o motivo. O formato desta aula é uma convenção editorial de projeto, não uma sintaxe especial de Markdown."},{"title":"Alternativas tornam a decisão avaliável","text":"Registre uma alternativa plausível e por que não foi escolhida neste contexto. Isso ajuda a reconhecer quando uma mudança de condições pode justificar revisão. Não apresente uma opção obviamente inútil só para parecer que houve comparação."},{"title":"Consequências e estado","text":"Descreva vantagens, custos e o estado da decisão: proposta, aceita ou substituída conforme a convenção usada. Quando houver nova decisão, preserve a ligação histórica para que o leitor descubra qual vale hoje, sem alterar o passado de forma silenciosa."}],"code":"# Decisão 001: separar guia e referência\n\nEstado: proposta de estudo. Data: 23/10/2026.\n\n## Contexto\n\nOperadores procuram passos de conferência; revisores procuram definições de campos. Um documento único ficou difícil de percorrer.\n\n## Decisão proposta\n\nManter um guia por tarefa e uma referência dos campos, ligados pelo índice.\n\n## Alternativa considerada\n\nManter tudo no README reduziria o número de arquivos, mas aumentaria o texto inicial para leitores com objetivos diferentes.\n\n## Consequências\n\nA entrada fica mais curta. A equipe precisa revisar os links entre os arquivos quando houver mudanças.\n","filename":"DECISAO-001.md","language":"markdown","run":"Salve como DECISAO-001.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um registro com estado proposto, contexto, escolha, alternativa e consequências. Ele não declara uma decisão operacional já aprovada.","quiz":{"question":"Por que registrar uma alternativa plausível?","options":["Para aumentar o tamanho sem acrescentar informação.","Para provar que nenhuma outra decisão será possível.","Para tornar a escolha avaliável e permitir reexaminar o motivo se o contexto mudar.","Para substituir todos os critérios por uma preferência visual."],"answer":2,"explanation":"Uma decisão bem descrita relaciona contexto e consequências; não promete validade eterna."},"exercises":[{"id":1,"title":"Outro contexto","prompt":"Se o manual tiver apenas uma página curta, reavalie a separação de arquivos.","hint":"A restrição que justificou a escolha pode ter mudado.","solution":"Um README único pode ser suficiente nesse cenário; registre a razão e o custo esperado antes de aceitar a revisão.","criteria":["Relaciona escolha ao contexto.","Não trata a decisão anterior como regra universal."]},{"id":2,"title":"Custo concreto","prompt":"Acrescente uma consequência negativa verificável da decisão proposta.","hint":"A manutenção também faz parte da escolha.","solution":"Registre que renomear uma seção pode exigir revisar links em mais de um arquivo, com uma tarefa de conferência correspondente.","criteria":["A consequência é específica.","Há uma forma de verificar ou administrar o custo."]},{"id":3,"title":"Decisão substituída","prompt":"Escreva como indicaria que a decisão 002 substituiu a 001.","hint":"Preserve o histórico e a decisão vigente.","solution":"Atualize o estado da 001 para substituída e ligue ao registro 002 realmente criado; o 002 deve explicar o novo contexto.","criteria":["O leitor identifica qual decisão vale.","A ligação histórica não aponta para arquivo inexistente na entrega."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":32,"level":11,"title":"Histórico de mudanças útil para leitores","goal":"Registrar o efeito de uma revisão sem confundir histórico com instrução vigente.","theory":[{"title":"Mudança deve dizer o efeito","text":"Um histórico útil explica o que o leitor precisa saber: regra corrigida, exemplo atualizado ou caminho alterado. Uma lista de nomes de arquivos pode não revelar o impacto. Escreva com foco no uso do material, sem relatar cada pequena edição de pontuação."},{"title":"Versão e data têm convenção","text":"A equipe escolhe como identificar revisões. Usar números de versão não significa que o projeto segue automaticamente uma política de versionamento específica. Declare a convenção e registre datas de forma que o leitor compreenda a ordem das mudanças."},{"title":"O procedimento atual fica no guia","text":"Histórico pode mencionar uma regra antiga para explicar a correção, mas deve encaminhar o leitor à orientação vigente. Não mantenha duas instruções ativas e incompatíveis. Uma revisão que muda exemplos exige conferir tutorial e referência juntos."}],"code":"# Histórico documental\n\nAs versões abaixo identificam revisões deste material fictício; não descrevem uma versão de software.\n\n## Revisão 1.1 — 23/10/2026\n\n### Corrigido\n\n- O tutorial agora distingue evidência anexada de evidência conferida.\n- O exemplo de saldo insuficiente registra pendência antes de confirmar.\n\n### Alterado\n\n- A referência de campos foi separada do guia de operação.\n\n## Revisão 1.0 — 22/10/2026\n\nPrimeira versão de estudo do procedimento e do cenário OS-1.\n","filename":"HISTORICO.md","language":"markdown","run":"Salve como HISTORICO.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um histórico com duas revisões e efeitos concretos. Ele distingue revisão documental de versão de software e não substitui o procedimento atual.","quiz":{"question":"Qual item de histórico é mais útil ao leitor?","options":["Arquivo alterado.","Várias coisas.","Mudança incrível e definitiva.","O tutorial passou a rejeitar o cenário saldo 1 com solicitação 2, registrando pendência."],"answer":3,"explanation":"O item identifica o comportamento ou a orientação alterada e permite conferir seu impacto."},"exercises":[{"id":1,"title":"Mudança de caminho","prompt":"Registre que GUIA.md foi movido para docs/GUIA.md e o efeito para links locais.","hint":"Descreva o que precisa ser conferido.","solution":"Informe a mudança de localização e a revisão dos links do índice e dos retornos afetados.","criteria":["O novo caminho está explícito.","O impacto na navegação é descrito."]},{"id":2,"title":"Coerência da revisão","prompt":"Uma correção mudou a quantidade do exemplo de 2 para 4. O que precisa ser revisto além do histórico?","hint":"O histórico não corrige o conteúdo sozinho.","solution":"Revise entrada, comparação, saída, referência e decisão do cenário nos documentos afetados.","criteria":["Inclui exemplos e resultado.","Não confunde registro de mudança com aplicação da correção."]},{"id":3,"title":"Regra atual","prompt":"Reescreva um item de histórico que diz antes confirmar sem conferir, agora talvez conferir.","hint":"A orientação vigente precisa ser inequívoca no guia.","solution":"Diga que a instrução anterior foi corrigida e que a regra vigente exige conferência antes da decisão; atualize o guia correspondente.","criteria":["A alteração tem efeito claro.","A regra vigente não fica apenas implícita."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":33,"level":11,"title":"Contribuição e checklist de revisão documental","goal":"Preparar critérios para que outra pessoa revise uma alteração com autonomia.","theory":[{"title":"Contribuir exige entender a entrega","text":"Um guia de contribuição explica o escopo dos documentos, as convenções relevantes e o que deve acompanhar uma mudança. Não precisa descrever todo o fluxo de Git para orientar revisão de conteúdo. O foco aqui é produzir uma alteração documental verificável."},{"title":"Critérios cobrem mais que sintaxe","text":"Um parser pode aceitar um documento com números errados, links enganosos e instruções incompletas. Inclua precisão do conteúdo, consistência entre exemplos, existência dos destinos e leitura no renderizador pretendido. Verificar apenas que o arquivo abre é insuficiente."},{"title":"Registre a evidência e os limites","text":"Uma lista marcada precisa dizer a que versão ou conjunto a revisão se refere. Se o revisor não conseguiu testar uma extensão, isso deve aparecer como pendência ou limite. Outra pessoa deve poder repetir a verificação com o contexto informado."}],"code":"# Contribuir com o manual\n\nUse dados fictícios e descreva a tarefa do leitor. Preserve os nomes de campos definidos na referência.\n\n## Antes de solicitar revisão\n\n- [ ] Explicar qual problema de leitura a mudança resolve.\n- [ ] Conferir os números e estados dos exemplos afetados.\n- [ ] Abrir links locais a partir de cada arquivo de origem.\n- [ ] Conferir a apresentação no renderizador declarado.\n- [ ] Registrar extensões não verificadas como pendências.\n\n## Evidência da revisão\n\nInforme os arquivos revisados, a data, o preview usado e os limites encontrados. Não marque uma conferência que não foi executada.\n","filename":"CONTRIBUIR.md","language":"markdown","run":"Salve como CONTRIBUIR.md e abra num preview GFM para conferir os checkboxes. Aplique a lista a um documento real do laboratório e registre apenas as verificações executadas.","expected":"Em GFM, uma lista de cinco verificações pendentes e instruções para registrar evidências e limites. O guia orienta o processo, sem executar as verificações.","quiz":{"question":"Uma revisão passou no parser, mas os números do exemplo se contradizem. Qual conclusão é adequada?","options":["A sintaxe aceita não comprova a correção editorial; os números precisam ser revistos.","O conteúdo está correto por definição.","O tema visual corrigirá a conta.","A contradição deixa de existir quando o arquivo é publicado."],"answer":0,"explanation":"Validade sintática e precisão do procedimento são critérios diferentes de revisão."},"exercises":[{"id":1,"title":"Critério de conteúdo","prompt":"Acrescente um item de revisão sobre coerência entre tutorial e referência de estados.","hint":"Ele deve ser verificável por outra pessoa.","solution":"Use Conferir se os estados nomeados no tutorial possuem a mesma definição da referência.","criteria":["O critério identifica os documentos comparados.","A condição pode ser verificada."]},{"id":2,"title":"Limite honesto","prompt":"Registre uma revisão em que Mermaid não pôde ser renderizado no ambiente disponível.","hint":"Não marque a visualização como conferida.","solution":"Informe que texto e cercas foram revisados, mas o diagrama aguarda teste num destino compatível; mantenha a alternativa textual.","criteria":["Distingue o que foi e não foi conferido.","A pendência possui próximo passo."]},{"id":3,"title":"Mudança pequena","prompt":"Uma pessoa corrigiu apenas um link local. Defina uma revisão proporcional.","hint":"Não é necessário reescrever o conjunto inteiro.","solution":"Abra o novo destino a partir do arquivo de origem, confirme o rótulo e revise os outros usos do mesmo caminho se existirem.","criteria":["A verificação está ligada à alteração.","O resultado e o contexto são registrados."]}],"source":"https://github.github.com/gfm/","caution":"","local":true,"hours":2,"minutes":45},{"id":34,"level":12,"title":"Diagnóstico de problemas de renderização","goal":"Investigar um resultado inesperado com uma hipótese e um exemplo mínimo.","theory":[{"title":"Comece pelo sintoma observável","text":"Descreva o que o preview mostra e o que você esperava, sem concluir de imediato que a ferramenta está quebrada. Uma tabela literal pode indicar dialeto sem extensão; uma lista solta pode indicar recuo; texto inteiro em código pode indicar cerca não fechada."},{"title":"Reduza o exemplo","text":"Copie apenas o trecho necessário para reproduzir o problema num arquivo de laboratório. Preserve os marcadores e o contexto próximo que afetam a análise. Ao reduzir, não remova justamente a linha que altera o tipo de bloco, como uma cerca ou um separador."},{"title":"Mude uma coisa e compare","text":"Escolha uma hipótese e altere um elemento de cada vez. Registre o resultado no mesmo renderizador antes de trocar de ferramenta. Uma comparação controlada ensina mais que mudar recuo, extensão e conteúdo ao mesmo tempo."}],"code":"# Registro de diagnóstico\n\n## Sintoma\n\nUma tabela apareceu como texto no preview de estudo.\n\n## Contexto\n\nO arquivo contém barras e separador de tabela. O modo informado pelo editor é CommonMark sem extensões.\n\n## Hipótese\n\nO visualizador não está usando a extensão de tabelas GFM.\n\n## Verificação proposta\n\nAbrir o mesmo trecho num modo GFM e comparar, sem alterar os dados da tabela.\n\n## Resultado\n\nPendente: registrar o comportamento observado antes de concluir a causa.\n","filename":"DIAGNOSTICO.md","language":"markdown","run":"Salve como DIAGNOSTICO.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um diagnóstico com sintoma, contexto, hipótese e verificação proposta; ele não declara um teste ainda não realizado.","quiz":{"question":"Qual mudança ajuda mais a investigar uma causa específica?","options":["Trocar todas as marcas, os dados e o editor ao mesmo tempo.","Alterar um fator por vez mantendo o contexto suficiente para reproduzir o sintoma.","Apagar a fonte antes de observar o preview.","Assumir que qualquer diferença é um defeito do site."],"answer":1,"explanation":"Uma comparação controlada permite associar o resultado à hipótese testada."},"exercises":[{"id":1,"title":"Cerca ausente","prompt":"Produza num laboratório um bloco de código sem fechamento e escreva um diagnóstico curto.","hint":"Observe onde o conteúdo seguinte passa a aparecer.","solution":"Registre o início do bloco, o texto afetado e a hipótese de fechamento ausente; restaure a cerca e compare.","criteria":["O sintoma é descrito.","A correção é testada isoladamente."]},{"id":2,"title":"Recuo da lista","prompt":"Investigue um subitem que virou lista principal sem mudar seu conteúdo.","hint":"Compare a coluna do marcador com o conteúdo do item pai.","solution":"Ajuste só o recuo no exemplo reduzido e confira se o pertencimento do subitem foi restabelecido.","criteria":["Mantém o conteúdo fixo no teste.","Relaciona resultado ao recuo."]},{"id":3,"title":"Conclusão proporcional","prompt":"Um preview GFM mostrou a tabela. O que você pode concluir sobre o preview anterior?","hint":"Separe evidência observada de certeza sobre toda a ferramenta.","solution":"Há evidência compatível com falta da extensão naquele modo. Confirme a configuração antes de afirmar que o programa inteiro não suporta tabelas.","criteria":["A conclusão respeita o escopo observado.","Propõe uma confirmação de configuração."]}],"source":"https://spec.commonmark.org/0.31.2/","caution":"","local":true,"hours":2,"minutes":45},{"id":35,"level":12,"title":"Portabilidade e matriz de compatibilidade","goal":"Revisar o mesmo conteúdo em contratos de renderização diferentes.","theory":[{"title":"Portável não significa idêntico","text":"Fontes, margens e cores podem mudar mesmo quando a estrutura continua correta. Defina o que deve permanecer: a regra, a hierarquia, os rótulos e os valores. Aparência idêntica entre todos os previews não é uma garantia da linguagem."},{"title":"Declare recursos e alternativas","text":"Uma matriz pequena pode relacionar recurso, dependência e alternativa. Ela serve para decidir se a extensão vale o custo para o público. Uma tabela GFM pode ter uma lista equivalente; um diagrama deve ter texto com a mesma regra."},{"title":"Verifique o destino real","text":"Um teste local não comprova como todos os serviços publicarão o conteúdo. Registre renderizador e opções, confira o contexto de links e valide o trecho que usa cada extensão. Se o destino não foi testado, mantenha isso como limite e não como sucesso presumido."}],"code":"# Contrato de portabilidade\n\n## Conteúdo que deve sobreviver\n\n- O saldo precisa atender à solicitação.\n- Uma evidência disponível ainda precisa ser conferida.\n- Pendências devem ser registradas antes de confirmar.\n\n## Recursos e alternativas\n\n- Títulos e listas: base CommonMark; mantenha hierarquia e rótulos claros.\n- Tabela GFM: alternativa em lista de pares campo e valor.\n- Mermaid: alternativa em texto com condição e dois resultados.\n- Front matter: alternativa com revisão e título escritos no corpo.\n\n## Registro de teste\n\nPreencher com o renderizador, suas opções e os resultados realmente observados.\n","filename":"COMPATIBILIDADE.md","language":"markdown","run":"Salve como COMPATIBILIDADE.md. Abra o preview CommonMark do editor e compare com o arquivo-fonte.","expected":"Um contrato legível sem extensões, com alternativas e critérios de verificação. O registro de teste está explicitamente pendente de preenchimento.","quiz":{"question":"Um documento mudou de fonte e cor, mas preservou títulos, regras e links. Isso prova falha de portabilidade?","options":["Sim, todos os renderizadores devem ter o mesmo tema.","Sim, Markdown define uma única família de fontes.","Não necessariamente; aparência e preservação do conteúdo são critérios distintos.","Não, porque links nunca precisam ser verificados."],"answer":2,"explanation":"A portabilidade deve ser avaliada conforme as propriedades relevantes; tema idêntico não é uma garantia da sintaxe."},"exercises":[{"id":1,"title":"Tabela para lista","prompt":"Converta uma tabela de dois campos em uma lista que mantenha o significado em CommonMark.","hint":"Preserve cabeçalhos como rótulos de cada valor.","solution":"Use um item por registro com os nomes dos campos em texto, evitando valores sem identificação fora da tabela.","criteria":["Os valores mantêm seus rótulos.","A alternativa não exige tabela GFM."]},{"id":2,"title":"Dois destinos","prompt":"Compare um documento num preview GFM e em um modo sem as extensões usadas.","hint":"Registre diferenças observadas, não expectativas.","solution":"Liste o que preservou sentido, o que virou texto literal e o que precisou de alternativa. Não declare teste de um destino que não abriu.","criteria":["Identifica os ambientes reais.","Distingue falha funcional de diferença visual."]},{"id":3,"title":"Critério de aceitação","prompt":"Defina três critérios para publicar um manual que será lido como texto e no GitHub.","hint":"Priorize informação e navegação.","solution":"Exija regra principal legível na fonte, links relativos conferidos no conjunto e alternativa textual para diagramas opcionais.","criteria":["Os critérios podem ser verificados.","Atendem aos dois contextos de leitura."]}],"source":"https://github.github.com/gfm/","caution":"","local":true,"hours":2,"minutes":45},{"id":36,"level":12,"title":"Projeto final: manual de OS e estoque","goal":"Entregar um conjunto coerente de documentos com percurso, referência, exemplos e revisão.","theory":[{"title":"A entrega orienta um leitor","text":"O projeto final reúne um ponto de entrada, um guia do operador e uma referência de regras. O exemplo desta aula fornece uma entrada de estudo; os outros documentos são entregas que você deve escrever e conferir. Não basta criar arquivos com títulos vazios."},{"title":"Uma regra em vários contextos","text":"O cenário OS-1 usa saldo 3 e solicitação 2. O guia deve explicar a conferência, a referência deve definir campos e estados e o histórico deve registrar as revisões. Ao acrescentar o cenário insuficiente, revise todos os resultados afetados para evitar contradições."},{"title":"Revisão e recuperação documental","text":"Guarde uma versão identificada do conjunto e descreva como voltar a uma cópia conhecida se uma edição quebrar a orientação. Recuperar documentos não restaura um banco de OS; esse limite deve ficar claro. A evidência final inclui links conferidos, exemplos consistentes e recursos do renderizador declarados."}],"code":"# Manual de OS e estoque de estudo\n\nPúblico: operador em treinamento e revisor. Este conjunto documenta um cenário fictício; não executa operações no sistema.\n\n## Percurso inicial\n\n1. Identifique a OS e o item solicitado.\n2. Compare a quantidade com o saldo disponível.\n3. Confira a evidência e registre a decisão ou a pendência.\n\n## Cenário principal\n\nA OS-1 solicita 2 unidades do item A, cujo saldo é 3. A análise numérica permite continuar a conferência. Uma confirmação válida do cenário deixa saldo 1.\n\n## Regra de pendência\n\nSe o saldo for 1 para uma solicitação de 2, ou se a evidência não puder ser conferida, registre a pendência antes de confirmar.\n\n## Arquivos a produzir no projeto\n\n- `docs/GUIA.md`: passos, pré-requisitos e resultados.\n- `docs/REFERENCIA.md`: campos, estados e limites.\n- `docs/HISTORICO.md`: revisões do conjunto.\n\n## Entrega\n\nDepois de criar os arquivos, acrescente links descritivos, confira a navegação e registre o renderizador utilizado e as limitações encontradas.\n","filename":"README.md","language":"markdown","run":"Salve como README.md na raiz do projeto documental. Produza os arquivos da lista em docs, crie os links e teste o percurso completo no renderizador escolhido.","expected":"Uma entrada documental completa para o cenário. O conjunto final só estará entregue após produzir os três arquivos, acrescentar e conferir links e registrar a revisão.","quiz":{"question":"O que conclui melhor o projeto documental?","options":["Apenas criar três arquivos vazios.","Marcar todos os checkboxes sem executar a revisão.","Adicionar extensões até o preview ficar diferente.","Um conjunto que outro leitor consegue percorrer, com exemplos coerentes, links conferidos e limites declarados."],"answer":3,"explanation":"A conclusão depende de orientar a tarefa e oferecer evidências proporcionais de revisão, não apenas de sintaxe ou aparência."},"exercises":[{"id":1,"title":"Conjunto integrado","prompt":"Escreva os três arquivos de docs, complete o índice do README e inclua links de retorno.","hint":"Use o guia para tarefa e a referência para contratos.","solution":"O guia deve conter os dois cenários de saldo; a referência define campos e estados; o histórico registra a revisão; o índice permite encontrar cada recurso.","criteria":["Os arquivos têm conteúdo útil e coerente.","A navegação foi conferida de cada origem."]},{"id":2,"title":"Revisão por outra pessoa","prompt":"Peça a um leitor, ou faça uma leitura sem consultar suas anotações, seguindo o cenário principal e o insuficiente.","hint":"Observe onde faltam informações para decidir.","solution":"Registre dúvidas encontradas e corrija pré-requisitos, rótulos e resultados. O cenário insuficiente não pode terminar com uma confirmação de baixa.","criteria":["A revisão registra problemas observáveis.","Os dois cenários terminam de acordo com as regras."]},{"id":3,"title":"Versão recuperável","prompt":"Descreva como guardar uma cópia identificada e restaurar o conjunto documental no laboratório.","hint":"Diferencie arquivos de orientação de dados de uma aplicação.","solution":"Guarde a pasta completa com data ou versão, restaure em outra pasta e confira arquivos e links antes de substituir a edição atual. Isso recupera documentos, não o estado de um sistema de OS.","criteria":["O procedimento preserva o conjunto e seus caminhos.","O escopo da recuperação está explícito."]}],"source":"https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/about-readmes","caution":"","local":true,"hours":2,"minutes":45}]};
